(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("hermes-corpus-2-e", [{"sp": "HDR", "t": "Ἑρμοῦ τοῦ Τρισμεγίστου λόγοι"}, {"sp": "HDR", "t": "Ὅτι οὐδὲν τῶν ὄντων ἀπόλλυται"}, {"sp": "N", "t": "Περὶ ψυχῆς καὶ σώματος, ὦ παῖ, νῦν λεκτέον, τρόπῳ μὲν ποίῳ ἀθάνατος ἡ ψυχή, ἐνεργείᾳ δὲ ποταπῇ ⟨…⟩ ἐστι συστάσεως σώματος καὶ διαλύσεως.", "st": "VIII.1"}, {"sp": "N", "t": "⟨…⟩ περὶ οὐδὲν γὰρ αὐτῶν ὁ θάνατος· ἀλλὰ ⟨ὄ⟩νο[η]μά ἐστιν Ἡ θανάτου προσηγορία[ς ἢ] κενὸν ἔργου.", "st": "VIII.1b"}, {"sp": "N", "t": "[ἢ κατὰ στέρησιν τοῦ πρώτου γράμματος λεγόμενος θάνατος ἀντὶ τοῦ ἀθάνατος.] ὁ γὰρ θάνατος ἀπώλειά[ς] ἐστιν, οὐδὲν δὲ τῶν ἐν τῷ κόσμῳ ἀπόλλυται. εἰ γὰρ δεύτερος θεὸς ὁ κόσμος, καὶ ζῷον ἀθάνατον, ἀδύνατόν ἐστι τοῦ ἀθανάτου ζῴου μέρος τι ἀποθανεῖν· πάντα δὲ τὰ ἐν τῷ κόσμῳ μέρη ἐστὶ τοῦ κόσμου. [μάλιστα δὲ ⟨ἀθάνατος⟩ ὁ ἄνθρωπος, τὸ λογικὸν ζῷον.]", "st": "VIII.1c"}, {"sp": "N", "t": "πρῶτος γὰρ πάντων, ὄντως καὶ ἀίδιος καὶ ἀγέννητος, [καὶ] ⟨ὁ⟩ δημιουργὸς τῶν ὅλων θεός· δεύτερος δὲ ὁ κατ’ εἰκόνα αὐτοῦ ὑπ’ αὐτοῦ γενόμενος, καὶ ὑπ’ αὐτοῦ συνεχόμενος καὶ τρεφόμενος, ἀθανατιζόμενος [ὡς] ὑπὸ ἀιδίου ⟨ὄντος τοῦ⟩ πατρὸς ἀείζωον ὡς [ἀθάνατος].", "st": "VIII.2"}, {"sp": "N", "t": "τὸ γὰρ ἀείζωον τοῦ ἀιδίου διαφέρει. ὁ μὲν γὰρ ⟨πατὴρ⟩ ὑπὸ ἑτέρου οὐκ ἐγένετο· εἰ δὲ καὶ ἐγένετο, ὑφ’ ἑαυτοῦ· ⟨μᾶλλον δὲ⟩ οὔποτε ἐγένετο, ἀλλ’ ἀεὶ ⟨ἔστιν·", "st": "VIII.2b"}, {"sp": "N", "t": "ὁ δὲ κόσμος ἀεὶ⟩ γίνεται. τὸ γὰρ αἴτιον ⟨τ⟩οῦ [ἀίδιόν ἐστι] ⟨εἶναι⟩ τὸ πᾶν ⟨ὁ πατήρ⟩· ὁ δὲ πατὴρ αὐτὸς ἑαυτοῦ αἴτιος. ὁ δὴ κόσμος ὑπὸ τοῦ πατρὸς ἀιδί⟨ου ὄντ⟩ος [καὶ] ἀθάνατος γέγονε.", "st": "VIII.2c"}, {"sp": "N", "t": "καὶ ὅσον ἦν τῆς ὕλης ὑποκείμενον τῷ ἑαυτοῦ ⟨θελήματι⟩, τὸ πᾶν ὁ πατὴρ σωματοποιήσας καὶ ὀγκώσας ἐποίησε σφαιροειδές, τοῦτο αὐτῷ τὸ ποιὸν περιθείς, οὖσαν καὶ αὐτὴν ἀθάνατον, καὶ ἔχουσαν ἀίδιον τὴν ὑλότητα.", "st": "VIII.3"}, {"sp": "N", "t": "πλέον δέ, τῶν Ζῴων τὰ ποιὰ ὁ πατὴρ ἐγκατασπείρας τῇ σφαίρᾳ ὥσπερ ἐν ἄντρῳ κατέκλεισε, πάσῃ ποιότητι κοσμῆσαι βουλόμενος τὸ μετ’ αὐτοῦ ⟨ἄ⟩ποιον.", "st": "VIII.3b"}, {"sp": "N", "t": "τῇ δὲ ἀθανασίᾳ περι⟨έ⟩βαλε τὸ πᾶν σῶμα, ἵνα μὴ ⟨ἡ⟩ ὕλη, [καὶ] τῆς τούτου συστάσεως θελήσασα ἀποστῆναι, διαλυθῇ εἰς τὴν ἑαυτῆς ἀταξίαν.", "st": "VIII.3c"}, {"sp": "N", "t": "ὅτε γὰρ ἦν ἀσώματος ἡ ὕλη, ὦ τέκνον, ἄτακτος ἦν· ἔχει δὲ καὶ ἐνθάδε ⟨ἄτακτόν⟩ τι περὶ τὰ [ἄλλα] μικρὰ [ποιὰ] ⟨ζῷα⟩ εἱλούμενον, τὸ τῆς αὐξήσεως καὶ [τὸ τῆς] μειώσεως [ὃν θάνατον οἱ ἄνθρωποι καλοῦσιν].", "st": "VIII.3d"}, {"sp": "N", "t": "αὕτη δὲ ἡ ἀταξία ⟨π⟩ερὶ τὰ ἐπίγεια ζῷα γίνεται. τῶν γὰρ οὐρανίων τὰ σώματα μίαν τάξιν ἔχει, ἣν εἴληχεν ἀπὸ τοῦ πατρὸς τὴν ἀρχήν· τηρεῖται δὲ αὕτη ὑπὸ τῆς ἑκάστου ἀποκαταστάσεως ἀδιάλυτος.", "st": "VIII.4"}, {"sp": "N", "t": "ἡ δὲ ἀποκατάστασις τῶν ἐπιγείων σωμάτων ⟨διαλυθείσης γίνεται τῆς⟩ συστάσεως· ⟨τ⟩ῇ δὲ διαλύσει ⟨τ⟩αύτῃ ἀποκαθίσταται εἰς τὰ ἀδιάλυτα σώματα, τουτέστι τὰ ἀθάνατα· καὶ οὕτω στέρησις γίνεται τῆς αἰσθήσεως, οὐκ ἀπώλεια ζωῆς [τῶν σωμάτων].", "st": "VIII.4b"}, {"sp": "N", "t": "τὸ δὲ τρίτον ζῷον ὁ ἄνθρωπος, κατ’ εἰκόνα τοῦ κόσμου γενόμενος, ⟨ν⟩οῦ⟨ν⟩ κατὰ βούλησιν τοῦ πατρὸς ἔχων παρὰ τὰ ἄλλα ἐπίγεια ζῷα, οὐ μόνον πρὸς τὸν δεύτερον θεὸν συμπάθειαν ἔχων, ἀλλὰ καὶ ἔννοιαν τοῦ πρώτου. τοῦ μὲν γὰρ αἰσθάνεται ὡς σώματος, τοῦ δὲ ἔννοιαν λαμβάνει ὡς ἀσωμάτου [καὶ νοῦ τοῦ ἀγαθοῦ].", "st": "VIII.5"}, {"sp": "N", "t": "— Τοῦτο οὖν οὐκ ἀπόλλυται τὸ ζῷον;", "st": "VIII.5b"}, {"sp": "N", "t": "— Εὐφήμησον, ὦ τέκνον, καὶ νόησον τί θεός, τί κόσμος, τί ζῷον ἀθάνατον, τί ζῷον διάλυτον.", "st": "VIII.5c"}, {"sp": "N", "t": "καὶ [νόησον ὅτι] ὁ μὲν κόσμος ὑπὸ τοῦ θεοῦ καὶ ἐν τῷ θεῷ, ὁ δὲ ἄνθρωπος ὑπὸ τοῦ κόσμου καὶ ἐν τῷ κόσμῳ·", "st": "VIII.5d"}, {"sp": "N", "t": "ἀρχὴ δὲ καὶ περιοχὴ καὶ σύστασις πάντων ὁ θεός.", "st": "VIII.5e"}, {"sp": "HDR", "t": "Περὶ νοήσεως καὶ αἰσθήσεως"}, {"sp": "N", "t": "Χθές, ὦ Ἀσκληπιέ, τὸν τέλειον ἀπ[οδ]έδωκα λόγον· νῦν δὲ ἀναγκαῖον ἡγοῦμαι ἀκόλουθον ἐκείνῳ καὶ τὸν περὶ αἰσθήσεως λόγον διεξελθεῖν.", "st": "IX.1"}, {"sp": "N", "t": "αἴσθησις γὰρ καὶ Νόησις διαφορὰν μὲν δοκοῦσιν ἔχειν, ὅτι ἡ μὲν ὑλική ἐστιν, ἡ δὲ οὐσιώδης· ἐμοὶ δὲ δοκοῦσιν ἀμφότεραι ἡνῶσθαι καὶ μὴ διαιρεῖσθαι, ἐν ἀνθρώποις λέγω· ἐν γὰρ τοῖς ἄλλοις ζῴοις ἡ αἴσθησις τῇ φύσει ἥνωται, ἐν δὲ ἀνθρώποις ⟨τ⟩ῇ νοήσει.", "st": "IX.1b"}, {"sp": "N", "t": "νοήσεως δὲ ὁ νοῦς διαφέρει τοσοῦτον ὅσον ὁ θεὸς θειότητος. ἡ μὲν γὰρ θειότης ὑπὸ τοῦ θεοῦ γίνεται, ἡ δὲ νόησις ὑπὸ τοῦ νοῦ, ἀδελφὴ οὖσα τοῦ λόγου. καὶ ὄργανα ⟨ταῦτα⟩ ἀλλήλων· οὔτε γὰρ ὁ λόγος ἐκφωνεῖται ⟨…⟩ χωρὶς νοήσεως, οὔτε ἡ νόησις [φαίνεται] χωρὶς λόγου.", "st": "IX.1c"}, {"sp": "N", "t": "ἡ οὖν αἴσθησις καὶ ἡ νόησις ἀμφότεραι εἰς τὸν ἄνθρωπον συνεπεισρέουσιν ἀλλήλαις, ὥσπερ συμπεπλεγμέναι· οὔτε γὰρ χωρὶς αἰσθήσεως δυνατὸν νοῆσαι, οὔτε αἰσθέσθαι χωρὶς νοήσεως [δυνατὸν δὲ νόησιν].", "st": "IX.2"}, {"sp": "N", "t": "⟨…⟩ χωρὶς αἰσθήσεως νοεῖσθαι, καθάπερ οἱ διὰ τῶν ὀνείρων φανταζόμενοι ὁράματα· ἐμοὶ δὲ δοκεῖ ⟨…⟩ τὸ γεγονέναι ἀμφοτέρας τὰς ἐνεργείας ἐν τῇ τῶν ὀνείρων ὄψει·", "st": "IX.2b"}, {"sp": "N", "t": "ἐγρηγοροῦσι γὰρ ⟨…⟩ αἰσθήσει. διῄρηται γὰ⟨ρ ἡ αἴσθησις⟩ εἴς τε τὸ σῶμα καὶ εἰς τὴν ψυχήν· καὶ ὅταν ἀμφότερα τὰ μέρη τῆς αἰσθήσεως πρὸς ἄλληλα συμφωνήσῃ, τότε ⟨συμβαίνει⟩ τὴν νόησιν ἐκφαίνε[ι]σθαι, ἀποκυηθεῖσαν ὑπὸ τοῦ νοῦ.", "st": "IX.2c"}, {"sp": "N", "t": "ὁ γὰρ νοῦς κύει πάντα τὰ νοήματα, ἀγαθὰ μέν, ὅταν ὑπὸ τοῦ θεοῦ τὰ σπέρματα λάβῃ, ἐναντία δέ, ὅταν ὑπό τινος τῶν δαιμόν[ι]ων, [μηδενὸς μέρους τοῦ κόσμου κενοῦ ὄντος δαίμονος,] τῷ ⟨μὴ⟩ ὑπὸ τοῦ θεοῦ πεφωτισμένῳ [δαίμονι] ὅστις ὑπεισελθὼν ἔσπειρε τῆς ἰδίας ἐνεργείας τὸ σπέρμα, καὶ ἐκύησεν ὁ νοῦς τὸ σπαρέν, μοιχείας, φόνους, πατροτυπίας, ἱεροσυλίας, ἀσεβείας [ἀγχόνας, κατὰ κρημνῶν καταφοράς, καὶ ἄλλα πάντα ὅσα δαιμόνων ἔργα].", "st": "IX.3"}, {"sp": "N", "t": "τοῦ γὰρ θεοῦ τὰ σπέρματα ὀλίγα, μεγάλα μέν⟨τοι⟩ καὶ καλὰ καὶ ἀγαθά, ἀρετὴ καὶ σωφροσύνη καὶ εὐσέβεια.", "st": "IX.4"}, {"sp": "N", "t": "εὐσέβεια δέ ἐστι θεοῦ γνῶσις· ὃν ὁ ἐπιγνούς, πλήρης γενόμενος πάντων τῶν ἀγαθῶν, τὰς νοήσεις θείας ἴσχει, καὶ οὐ τοῖς πολλοῖς ὁμοίας.", "st": "IX.4b"}, {"sp": "N", "t": "διὰ τοῦτο οἱ ἐν γνώσει ὄντες οὔτε τοῖς πολλοῖς ἀρέσκουσιν, οὔτε οἱ πολλοὶ αὐτοῖς· μεμηνέναι δὲ δοκοῦσι, καὶ γέλωτα ὀφλισκάνουσι, μισούμενοί τε καὶ καταφρονούμενοι, καὶ τάχα που καὶ φονευόμενοι.", "st": "IX.4c"}, {"sp": "N", "t": "τὴν γὰρ κακίαν ἐνθάδε δεῖν οἰκεῖν εἶπον, ἐν τῷ ἑαυτῆς χωρίῳ οὖσαν· χωρίον γὰρ αὐτῆς ἡ γῆ, οὐχ ὁ κόσμος, ὡς ἔνιοί ποτε ἐροῦσι βλασφημοῦντες.", "st": "IX.4d"}, {"sp": "N", "t": "ὁ μέντοι θεοσεβὴς πάντα ὑποστήσει ἀ⟨ντ⟩ισχόμενος τῆς γνώσεως. πάντα γὰρ τῷ τοιούτῳ, κἂν τοῖς ἄλλοις ⟨ᾖ⟩ [τὰ] κακά, ἀγαθά ἐστι· καὶ ἐπιβουλευόμενος πάντα ἀναφέρει εἰς τὴν γνῶσιν, καὶ τὰ κακὰ μόνος ἀγαθοποιεῖ.", "st": "IX.4e"}, {"sp": "N", "t": "ἐπάνειμι πάλιν ἐπὶ τὸν τῆς αἰσθήσεως λόγον. ἀνθρώπινον οὖν τὸ κοινωνῆσαι αἴσθησιν νοήσει· οὐ πᾶς δὲ ἄνθρωπος, ὡς προεῖπον, ἀπολαύει τῆς νοήσεως·", "st": "IX.5"}, {"sp": "N", "t": "[ἀλλ’ ὁ μὲν ὑλικός, ὁ δὲ οὐσιώδης.] ὁ μὲν γὰρ μετὰ κακίας [ὑλικός] ⟨νοεῖ⟩, ὡς ἔφην, ἀπὸ τῶν δαιμόνων τὸ σπέρμα τῆς νοήσεως ἴσχων, οἱ δὲ μετὰ τοῦ ἀγαθοῦ [οὐσιωδῶς], ὑπὸ τοῦ θεοῦ σωζόμενοι.", "st": "IX.5b"}, {"sp": "N", "t": "ὁ μὲν γὰρ θεός, πάντων δημιουργὸς [δημιουργ] ὤν, πάντα ποιεῖ [μὲν] ἑαυτῷ ὅμοια, ταῦτα δ’, ἀγαθὰ γενόμενα, ἐν τῇ χρήσει τῆς ἐνεργείας †αφορα†·", "st": "IX.5c"}, {"sp": "N", "t": "ἡ γὰρ κοσμικὴ φορά, τρέπουσα τὰς γενέσεις, ποιὰς ποιεῖ, τὰς μὲν ῥυπαίνουσα τῇ κακίᾳ, τὰς δὲ καθαίρουσα τῷ ἀγαθῷ.", "st": "IX.5d"}, {"sp": "N", "t": "καὶ γὰρ ὁ κόσμος, ὦ Ἀσκληπιέ, αἴσθησιν ἰδίαν καὶ Νόησιν ἔχει, οὐχ ὁμοίαν τῇ ἀνθρωπείᾳ, οὐδὲ ⟨οὕτ⟩ως ποικίλην, ἀλλ⟨ὰ⟩ [ως δὲ] κρείττω καὶ ἁπλουστέραν.", "st": "IX.6"}, {"sp": "N", "t": "ἡ γὰρ αἴσθησις καὶ νόησις τοῦ κόσμου μία ἐστί, τὸ πάντα ποιεῖν καὶ εἰς ἑαυτὸν ἀποποιεῖν, ὄργανον ⟨ὄντα⟩⟩ τῆς τοῦ θεοῦ βουλήσεως, καὶ ὄντως ⟨ἐπὶ τοῦτο⟩ [ὀργανο] ποιηθέν⟨τα⟩, ἵνα πάντων ⟨τῶν⟩ παρ’ ἑαυτῷ ἀπὸ τοῦ θεοῦ λαβὼν τὰ σπέρματα ⟨καὶ⟩ φυλάττων ἐν ἑαυτῷ πάντα ποιῇ ἐνεργῶς. καὶ διαλύων πάντα, ἀνανεοῖ [καὶ] ⟨τὰ⟩ δια-[τοῦτο]-λυθέντα, ὥσπερ ἀγαθὸς [ζωῆς] γεωργὸς τῇ καταβολῇ ἀνανέωσιν αὐτοῖς [φερόμενος] παρέχων.", "st": "IX.6b"}, {"sp": "N", "t": "οὐκ ἔστιν ὃ μὴ ζωογονεῖ· φερόμενος δὲ πάντα ζωοποιεῖ· καὶ ὁμοῦ τόπος ἐστὶ καὶ δημιουργὸς ζωῆς.", "st": "IX.6c"}, {"sp": "N", "t": "τὰ δὲ σώματα ἀπὸ ὕλης, ἐν διαφορᾷ· [τὰ μὲν γάρ ἐστιν ἐκ γῆς, τὰ δὲ ἐξ ὕδατος, τὰ δὲ ἐξ ἀέρος, τὰ δὲ ἐκ πυρός·] πάντα δέ ἐστι σύνθετα, καὶ τὰ μὲν μᾶλλον, τὰ δὲ ἁπλούστερα·", "st": "IX.7"}, {"sp": "N", "t": "μᾶλλον μὲν τὰ βαρύτερα, ἧττον δὲ τὰ κουφότερα.", "st": "IX.7b"}, {"sp": "N", "t": "τὸ δὲ τάχος αὐτοῦ τῆς φορᾶς τὴν ποικιλίαν τῶν [ποιῶν] γενέσεων ἐργάζεται. πνοὴ γάρ, οὖσα πυκνοτάτη, προτείνει τὰ ποιὰ τοῖς σώμασι μετὰ ἑνὸς πληρώματος τῆς ζωῆς.", "st": "IX.7c"}, {"sp": "N", "t": "[πατὴρ μὲν οὖν ὁ θεὸς τοῦ κόσμου, ὁ δὲ κόσμος τῶν ἐν τῷ κόσμῳ· καὶ ὁ μὲν κόσμος υἱὸς τοῦ θεοῦ, τὰ δὲ ἐν τῷ κόσμῳ ⟨υἱοὶ⟩ [ὑπὸ] τοῦ κόσμου.] καὶ εἰκότως κόσμος κέκληται·", "st": "IX.8"}, {"sp": "N", "t": "κοσμεῖ⟨ται⟩ γὰρ τὰ πάντα τῇ ποικιλίᾳ τῆς γενέσεως, καὶ τῷ ἀδιαλείπτῳ τῆς ζωῆς, καὶ ⟨τῷ⟩ ἀκοπιάστῳ τῆς ἐνεργείας, καὶ τῷ τάχει ⟨τῆς φορᾶς, καὶ τῷ ἀτρέπτῳ⟩ τῆς ἀνάγκης, καὶ τῇ συστάσει τῶν στοιχείων, καὶ τῇ τάξει τῶν γινομένων.", "st": "IX.8b"}, {"sp": "N", "t": "ὁ αὐτὸς οὖν κόσμος καὶ †ἀναγκαίως† καὶ οἰκείως καλοῖτο.", "st": "IX.8c"}, {"sp": "N", "t": "πάντων οὖν τῶν ζῴων ἡ αἴσθησις καὶ νόησις ἔξωθεν ἐπεισέρχεται, εἰσπνέουσα ἀπὸ τοῦ περιέχοντος· ὁ δὲ κόσμος, ἅπαξ λαβὼν ἅμα τῷ γενέσθαι, ἀπὸ τοῦ θεοῦ λαβὼν ἔχει.", "st": "IX.9"}, {"sp": "N", "t": "ὁ δὲ θεὸς οὐχ ὥσπερ ἐνίοις δόξει ἀναίσθητός ἐστι καὶ ἀνόητος· ὑπὸ γὰρ δεισιδαιμονίας βλασφημοῦσι.", "st": "IX.9b"}, {"sp": "N", "t": "πάντα γὰρ ὅσα ἔστιν, ὦ Ἀσκληπιέ, ταῦτα ἐν τῷ θεῷ ἐστι, καὶ ὑπὸ τοῦ θεοῦ γινόμενα, καὶ ἐκεῖθεν ἠρτημένα, τὰ μὲν διὰ σωμάτων ἐνεργοῦντα, τὰ δὲ διὰ οὐσίας ψυχικῆς κινοῦντα, τὰ δὲ διὰ πνεύματος ζωοποιοῦντα, τὰ δὲ τὰ κεκμηκότα ὑποδεχόμενα.", "st": "IX.9c"}, {"sp": "N", "t": "[καὶ εἰκότως.] μᾶλλον δὲ λέγω ὅτι οὐκ αὐτὸς αὐτὰ ἔχει, ἀλλὰ τὸ ἀληθὲς ἀποφαίνομαι, αὐτὸς ἅπαντά ἐστιν [οὐκ ἔξωθεν αὐτὰ προσλαμβάνων, ἔξω δὲ ἐπιδιδούς.] καὶ τοῦτό ἐστιν ἡ αἴσθησις καὶ νόησις τοῦ θεοῦ, τὸ τὰ πάντα ἀεὶ κινεῖν.", "st": "IX.9d"}, {"sp": "N", "t": "καὶ οὐκ ἔσται ποτὲ χρόνος ὅτε ἀπολειφθήσεταί τι τῶν ὄντων· [ὅταν δὲ λέγω τῶν ὄντων, λέγω τοῦ θεοῦ·] τὰ γὰρ ὄντα ὁ θεὸς ἔχει, καὶ οὔτε αὐτοῦ οὐδὲν ἐκτὸς οὔτε αὐτὸς οὐδενός.", "st": "IX.9e"}, {"sp": "N", "t": "ταῦτά σοι, Ἀσκληπιέ, ἐννοοῦντι ⟨μὲν⟩ ἀληθῆ δόξειεν ἄν, ⟨μὴ ἐν⟩νοοῦντι δὲ ἄπιστα·", "st": "IX.10"}, {"sp": "N", "t": "τῷ γὰρ νοῆσαι ἕπεται τὸ πιστεῦσαι, τὸ ἀπιστῆσαι δὲ τῷ μὴ νοῆσαι.", "st": "IX.10b"}, {"sp": "N", "t": "ὁ γὰρ λόγος [μ] οὐ φθάνει μέχρι τῆς ἀληθείας· ὁ δὲ νοῦς μέγας ἐστί, καὶ ὑπὸ τοῦ λόγου μέχρι τινὸς ὁδηγηθείς, φθάνει Μέχρι τῆς ἀληθείας·", "st": "IX.10c"}, {"sp": "N", "t": "καὶ περινοήσας τὰ πάντα, καὶ εὑρὼν σύμφωνα τοῖς ὑπὸ τοῦ λόγου ἑρμηνευθεῖσιν, ἐπίστευσε, καὶ τῇ καλῇ πίστει ἐπανεπαύσατο.", "st": "IX.10d"}, {"sp": "N", "t": "τοιγ⟨αρ⟩οῦν τὰ προειρημένα [ὑπὸ τοῦ θεοῦ] νοήσασι μὲν πιστὰ, μὴ νοήσασι δὲ ἄπιστα.", "st": "IX.10e"}, {"sp": "N", "t": "ταῦτα καὶ τοσαῦτα περὶ νοήσεως καὶ αἰσθήσεως λεγέσθω.", "st": "IX.10f"}, {"sp": "HDR", "t": "Κλείς"}, {"sp": "N", "t": "Τὸν χθὲς λόγον, ὦ Ἀσκληπιέ, σοὶ ἀνέθηκα· τὸν δὲ σήμερον δίκαιόν ἐστι τῷ Τὰτ ἀναθεῖναι, ἐπεὶ καὶ τῶν ⟨γ⟩ενικῶν λόγων τῶν πρὸς αὐτὸν λελαλημένων ἐστὶν ἐπιτομή.", "st": "X.1"}, {"sp": "N", "t": "ὁ μὲν οὖν θεὸς καὶ πατήρ, καὶ τὸ ἀγαθόν, ὦ Τάτ, τὴν αὐτὴν ἔχει φύσιν, μᾶλλον δὲ [καὶ] ἐνέργειαν.", "st": "X.1b"}, {"sp": "N", "t": "ἡ μὲν γὰρ φύσ⟨ις γενέσ⟩εως καὶ αὐξήσεώς ἐστι προσηγορία, ἅπερ ἐστὶ περὶ τὰ μεταβλητὰ καὶ κινητά·", "st": "X.1c"}, {"sp": "N", "t": "⟨ἡ δὲ τοῦ θεοῦ ἐνέργεια περὶ τὰ ἀμετάβλητα⟩ καὶ ἀκίνητα, τουτέστι τὰ θεῖα [τε], καὶ ⟨τὰ⟩ ἀνθρώπεια ὧν αὐτὸς βούλεται εἶναι. ἀλλαχοῦ δὲ ⟨περὶ⟩ ἐνεργειῶν καθὼς καὶ ἐπὶ τῶν ἄλλων ἐδιδάξαμεν θείων τε καὶ ἀνθρωπίνων· ἃ δεῖ νοεῖν ἐπὶ τούτου.", "st": "X.1d"}, {"sp": "N", "t": "ἡ γὰρ τούτου ἐνέργεια ἡ θέλησίς ἐστι· καὶ ἡ οὐσία αὐτοῦ τὸ θέλειν πάντα εἶναι. τί γάρ ἐστι⟨ν ὁ⟩ θεὸς καὶ πατὴρ [καὶ τὸ ἀγαθὸν] ἢ τὸ τῶν πάντων εἶναι οὐκέτι ὄντων; ἀλλὰ ὕπαρξις αὕτη τῶν ὄντων. τοῦτο ὁ θεός, τοῦτο ὁ πατήρ. τούτῳ ⟨δὲ πρόσεστι⟩ τὸ ἀγαθόν, ⟨τοιοῦτο ὂν⟩ ὃ μηδεν⟨ὶ⟩ πρόσεστι τῶν ἄλλων.", "st": "X.2"}, {"sp": "N", "t": "ὁ μὲν γὰρ κόσμος [καὶ ὁ ἥλιος] τῶν κατὰ μετουσίαν ⟨ἀγαθῶν⟩ καὶ αὐτὸς πατήρ, οὐκέτι δὲ τοῦ ἀγαθοῦ τοῖς ζῴοις ἴσως αἴτιός ἐστιν·", "st": "X.2b"}, {"sp": "N", "t": "οὐδὲ ⟨γὰρ⟩ τοῦ ζῆν· εἰ δέ [τοῦτο οὕτως ἔχει], πάντως μέντοι ἀναγκαζόμενος ὑπὸ τοῦ [ἀγαθοῦ] θελήματος ⟨τοῦ θεοῦ⟩, οὗ χωρὶς οὔτε εἶναί ⟨τι⟩ οὔτε γενέσθαι δυνατόν.", "st": "X.2c"}, {"sp": "N", "t": "αἴτιος δέ, ὡς πατὴρ τοῖς τέκνοις, καὶ τῆς σπορᾶς καὶ τῆς τροφῆς, ⟨παρὰ τοῦ θεοῦ⟩ τὴν ⟨χ⟩ορηγίαν λαβὼν τοῦ ἀγαθοῦ [διὰ τοῦ ἡλίου].", "st": "X.3"}, {"sp": "N", "t": "τὸ γὰρ ἀγαθόν ἐστι τὸ ποιητικόντοῦτο δὲ οὐ δυνατὸν ἐγγενέσθαι ἄλλῳ τινὶ ἢ μόνῳ ἐκείνῳ, τῷ μηδὲν μὲν λαμβάνοντι, πάντα δὲ θέλοντι εἶναι.", "st": "X.3b"}, {"sp": "N", "t": "οὐ γὰρ ἐρῶ, ὦ Τάτ, ποιοῦντι· ὁ γὰρ ποιῶν ἐλλιπής ἐστι πολλῷ χρόνῳ, †ἐν ᾧ† ὅτε μὲν ποιεῖ, ὅτε δὲ οὐ ποιεῖ. καὶ ποιότητας καὶ ποσότητας ⟨ποιεῖ⟩· ποτὲ μὲν γὰρ ποσὰ καὶ ποιὰ ⟨ποιεῖ⟩, ὅτε δὲ τὰ ἐναντία.", "st": "X.3c"}, {"sp": "N", "t": "ὁ δὲ θεὸς [καὶ πατὴρ καὶ τὸ ἀγαθὸν] τῷ ⟨θέλειν⟩ εἶναι τὰ πάντα ⟨πάντων πατήρ⟩.", "st": "X.3d"}, {"sp": "N", "t": "οὕτως ἄρα [ταῦτα] τῷ δυναμένῳ ἰδεῖν καὶ γὰρ ταῦτα θέλει εἶναι, καὶ ἔστι καὶ αὐτά. μάλιστα δὲ αὐτὸ· καὶ γὰρ τὰ ἄλλα πάντα διὰ τοῦτο ἔστιν. ⟨…⟩ ἴδιον γὰρ τοῦ ἀγαθοῦ τὸ γνωρίζεσθαι ἔστι τὸ ἀγαθὸν ὦ Τὰτ.", "st": "X.4"}, {"sp": "N", "t": "— Ἐπλήρωσας ἡμᾶς, ὦ πάτερ, τῆς ἀγαθῆς καὶ καλλίστης θέας· καὶ ὀλίγου δεῖν ⟨ἐπ⟩εσκιάσθη μου ὁ τοῦ νοῦ ὀφθαλμὸς ὑπὸ τῆς τοιαύτης †θέας†.", "st": "X.4b"}, {"sp": "N", "t": "— Οὐ γὰρ ὥσπερ ἡ τοῦ ἡλίου ἀκτὶς πυρώδης οὖσα καταυγάζει καὶ μύειν ποιεῖ τοὺς ὀφθαλμούς, οὕτω καὶ ἡ τοῦ ἀγαθοῦ θέα· τοὐναντίον δὲ ἐκλάμπει [καὶ] ἐπὶ τοσοῦτον, ἐφ’ ὅσον δύναται ὁ θεώμενος δέξασθαι τὴν ἐπεισροὴν τῆς νοητῆς λαμπηδόνος.", "st": "X.4c"}, {"sp": "N", "t": "ὀξυτέρα μὲν γάρ ἐστιν εἰς τὸ καθικνεῖσθαι, ἀβλαβὴς δέ, καὶ πάσης ἀθανασίας ἀνάπλεως.", "st": "X.4d"}, {"sp": "N", "t": "⟨καὶ μ⟩ὴν οἱ δυνάμενοι πλέον τι ἀρύσασθαι τῆς θέας κατακοιμίζονται πολλάκις δὴ ὑπὸ τοῦ σώματος· ⟨ἀπολυθέντες δὲ τοῦ σώματος⟩ εἰς τὴν καλλίστην ὄψιν ⟨ἐνέτυχον⟩, ὥσπερ Οὐρανὸς καὶ Κρόνος, οἱ ἡμέτεροι πρόγονοι, ἐντετυχήκασιν.<br>— Εἴθε καὶ ἡμεῖς, ὦ πάτερ.", "st": "X.5"}, {"sp": "N", "t": "— Εἴθε γάρ, ὦ τέκνον· νῦν δὲ ἔτι ἀτονοῦμεν πρὸς τὴν ὄψιν, καὶ οὕτως οὐκ ἰσχύομεν ἀναπετάσαι ἡμῶν τοὺς τοῦ νοῦ ὀφθαλμούς, καὶ θεάσασθαι τὸ κάλλος τοῦ ἀγαθοῦ, ἐκεῖνο[υ] τὸ ἄφθαρτον, τὸ ⟨ἀλ⟩άλη[π]τον.", "st": "X.5b"}, {"sp": "N", "t": "τότε γὰρ αὐτὸ ὄψει, ὅταν μηδὲν περὶ αὐτοῦ ἔχῃς εἰπεῖν· ἡ γὰρ γνῶσις αὐτοῦ Βαθεῖα σιωπή ἐστι, καὶ καταργία πασῶν τῶν αἰσθήσεων.", "st": "X.5c"}, {"sp": "N", "t": "οὔτε γὰρ ἄλλο τι δύναται νοῆσαι ὁ τοῦτο νοήσας, οὔτε ἄλλο τι θεάσασθαι ὁ τοῦτο θεασάμενος, οὔτε περὶ ἄλλου τινὸς ἀκοῦσαι, οὔτε τὸ σύνολον τὸ σῶμα κινῆσαι· πασῶν γὰρ τῶν σωματικῶν αἰσθήσεών τε καὶ κινήσεων ἐπιλαθόμενος ἀτρεμεῖ·", "st": "X.6"}, {"sp": "N", "t": "περιλάμψαν δὲ [πάντα] τὸν νοῦν, [καὶ] τὴν ὅλην ψυχὴν ἀναλαμβ⟨άν⟩ει καὶ ἀνέλκει διὰ τοῦ σώματος, καὶ ὅλον αὐτὸν εἰς οὐσίαν μεταβάλλει.", "st": "X.6b"}, {"sp": "N", "t": "ἀδύνατον γάρ, ὦ τέκνον, ψυχὴν ἀποθεωθῆναι ἐν σώματι ἀνθρώπου ⟨μένουσαν· ἀλλὰ χρὴ μεταβληθῆναι αὐτήν, καὶ οὕτω δὴ⟩ θεασαμένην τοῦ ἀγαθοῦ ⟨τὸ⟩ κάλλος [τῷ] ἀποθεωθῆναι.", "st": "X.6c"}, {"sp": "N", "t": "— Πῶς λέγεις, ὦ πάτερ;", "st": "X.7"}, {"sp": "N", "t": "— Πάσης ψυχῆς, ὦ τέκνον, διαιρετῆς μεταβολαὶ ⟨πολλαὶ⟩ δή.", "st": "X.7b"}, {"sp": "N", "t": "— Πῶς πάλιν διαιρετῆς;", "st": "X.7c"}, {"sp": "N", "t": "— Οὐκ ἤκουσας ἐν τοῖς γενικοῖς, ὅτι ἀπὸ μιᾶς ψυχῆς τῆς τοῦ παντὸς πᾶσαι αἱ ψυχαί εἰσιν αὗται, ⟨αἱ⟩ ἐν τῷ παντὶ κόσμῳ κυλινδούμεναι ὥσπερ ἀπονενεμημέναι;", "st": "X.7d"}, {"sp": "N", "t": "τούτων τοίνυν τῶν ψυχῶν πολλαὶ αἱ μεταβολαί, τῶν μὲν ἐπὶ τὸ εὐτυχέστερον, τῶν δὲ ἐπὶ τὸ ἐναντίον.", "st": "X.7e"}, {"sp": "N", "t": "αἱ μὲν γὰρ ἑρπετώδεις οὖσαι εἰς ἔνυδρα μεταβάλλουσιν, αἱ δὲ ἔνυδροι εἰς χερσαῖα, αἱ δὲ χερσαῖαι εἰς πετεινά, αἱ δὲ ἀέριαι εἰς ἀνθρώπους·", "st": "X.7f"}, {"sp": "N", "t": "αἱ δὲ ἀνθρώπειαι, ἀρχὴν ἀθανασίας [ι]σχοῦσαι, εἰς δαίμονας μεταβάλλουσιν, εἶθ’ οὕτως εἰς τὸν τῶν θεῶν χορὸν χωρ[ευ]οῦσι· [χοροὶ δὲ δύο θεῶν, ὁ μὲν τῶν πλανωμένων, ὁ δὲ τῶν ἀπλανῶν·] καὶ αὕτη ψυχῆς ἡ τελειοτάτη δόξα.", "st": "X.7g"}, {"sp": "N", "t": "ψυχὴ δὲ εἰς ἀνθρώπου σῶμα εἰσελθοῦσα, ἐὰν κακὴ μείνῃ, οὐ[τε] γεύεται ἀθανασίας, [οὔτε τοῦ ἀγαθοῦ μεταλαμβάνει,] παλίσσυρτος δὲ τὴν ὁδὸν ὑποστρέφει τὴν ἐπὶ τὰ ἑρπετά· καὶ αὕτη καταδίκη ψυχῆς κακῆς.", "st": "X.8"}, {"sp": "N", "t": "κακία δὲ ψυχῆς ἀγνωσία· ψυχὴ γὰρ μηδὲν γνοῦσα τῶν ὄντων, μηδὲ τὴν τούτων φύσιν, μηδὲ τὸ ἀγαθόν, τυφλώττουσα δέ, ἐντινάσσε⟨τα⟩ι τοῖς σωματικοῖς πάθεσι, καὶ ἡ κακοδαίμων ἀγνοήσασα ἑαυτὴν δουλεύει σώμασιν ἀλλοκότοις καὶ μοχθηροῖς, ὥσπερ φορτίον βαστάζουσα τὸ σῶμα, καὶ οὐκ ἄρχουσα, ἀλλ’ ἀρχομένη.", "st": "X.8b"}, {"sp": "N", "t": "αὕτη κακία ψυχῆς. τοὐναντίον δὲ ἀρετὴ ψυχῆς γνῶσις· ὁ γὰρ γνοὺς καὶ ἀγαθὸς καὶ εὐσεβής, καὶ ἤδη θεῖος.", "st": "X.9"}, {"sp": "N", "t": "— Τίς δέ ἐστιν οὗτος, ὦ πάτερ;", "st": "X.9b"}, {"sp": "N", "t": "— Ὁ μὴ πολλὰ λαλῶν, μηδὲ πολλὰ ἀκούων. ὁ γὰρ διαλόγοις σχολάζων καὶ ἀκοαῖς, ὦ τέκνον, σκιαμαχεῖ· ὁ γὰρ θεὸς καὶ πατὴρ [καὶ τὸ ἀγαθὸν] οὔτε λέγεται οὔτε ἀκούεται.", "st": "X.9c"}, {"sp": "N", "t": "τούτου δὲ οὕτως ἔχοντος ἐν πᾶσι τοῖς οὖσιν †αἱ αἰσθήσεις εἰσὶ† διὰ τὸ μὴ δύνασθαι εἶναι χωρὶς αὐτοῦ.", "st": "X.9d"}, {"sp": "N", "t": "γνῶσις δὲ αἰσθήσεως πολὺ διαφέρει. αἴσθησις μὲν γὰρ γίνεται τοῦ ⟨ὑλικοῦ⟩ ἐπικρατοῦντος, ⟨ὀργάνῳ χρωμένη τῷ σώματι,⟩ γνῶσις δὲ [ἐστιν ἐπιστήμης τὸ τέλος, ἐπιστήμη δὲ δῶρον τοῦ θεοῦ·", "st": "X.10"}, {"sp": "N", "t": "πᾶσα γὰρ ἐπιστήμη] ἀσώματος, ὀργάνῳ χρωμένη αὐτῷ τῷ νοΐ· ὁ δὲ νοῦς τῷ σώματι ⟨ἐναντίος⟩.", "st": "X.10b"}, {"sp": "N", "t": "ἀμφότερα οὖν χωρεῖ εἰς σῶμα ⟨εἰσδῦσα ψυχή⟩, τά τε νοητὰ καὶ τὰ ὑλικά. ἐξ ἀντιθέσεως γὰρ καὶ ἐναντιότητος δεῖ τὰ πάντα συνεστάναι. καὶ τοῦτο ἄλλως εἶναι ἀδύνατον. ⟨…⟩", "st": "X.10c"}, {"sp": "N", "t": "— Τί[ς] οὖν ὁ ὑλικὸς θεὸς ὁδί, ⟨ὁ κόσμος⟩;", "st": "X.10d"}, {"sp": "N", "t": "— Ο⟨ὐ⟩ κακὸς ⟨ὁ⟩ κόσμος, οὐκέ[σ]τι δὲ ἀγαθός·", "st": "X.10e"}, {"sp": "N", "t": "ὑλικὸς γάρ, καὶ [ευ]παθητός. καὶ πρῶτος μὲν πάντων παθητῶν, δεύτερος δὲ τῶν ὄντων, [καὶ αὐτοδεὴς] καὶ αὐτὸς [ποτὲ μὲν γενόμενος] ἀεὶ [δὲ] ὤν, ὢν δὲ ἐν γενέσει, καὶ γινόμενος ἀεὶ ⟨τῇ⟩ γενέσει τῶν ποιῶν καὶ τῶν ποσῶν. κινητὸς [γ]ἄρ⟨α⟩· πᾶσα γὰρ ὑλικὴ κίνησις γένεσίς ἐστιν.", "st": "X.10f"}, {"sp": "N", "t": "ἡ δὲ νοητὴ στάσις κινεῖ τὴν ὑλικὴν κίνησιν τὸν τρόπον τοῦτον.", "st": "X.11"}, {"sp": "N", "t": "ἐπεὶ ὁ κόσμος σφαῖρά ἐστι, τουτέστι κεφαλή, [κεφαλῆς δὲ οὐδὲν ὑπεράνω ὑλικόν, ὥσπερ οὐδὲ ποδῶν οὐδὲν νοητὸν ὑποκάτω, πᾶν δὲ ὑλικόν,] [†νοῦς δὲ κεφαλὴ αὕτη† σφαιρικῶς κινουμένη, τοῦτο ἔστι κεφαλικῶς,] ὅσα οὖν προσήνωται τῷ ὑμένι τῆς κεφαλῆς ταύτης, ⟨ἐν ᾧ...⟩ ἐστὶν ἡ ψυχή, ἀθάνατα πέφυκεν, [ὥσπερ] ἐν ψυχῇ δὲ σώματος πεποιημένου [καὶ] πλείω τοῦ σώματος τὴν ψυχὴν ἔχοντα·", "st": "X.11b"}, {"sp": "N", "t": "τὰ δὲ πόρρω τοῦ ὑμένος θνητά, πλέον ἔχοντα τῆς ψυχῆς τὸ σῶμα.", "st": "X.11c"}, {"sp": "N", "t": "πᾶν δὲ ζῷον ὥστε τὸ πᾶν ἔκ τε ὑλικοῦ καὶ νοητοῦ συνέστηκεν. ἐμψύχου δὲ ⟨τοῦ⟩ σώματος πεποιημένου, ⟨τὸ⟩ πᾶν δὴ ζῷον.", "st": "X.11d"}, {"sp": "N", "t": "καὶ ὁ μὲν κόσμος πρῶτον τῶν ἄλλων ζῴων· ὁ δὲ ἄνθρωπος δεύτερον ζῷον μετὰ τὸν κόσμον, πρῶτον δὲ τῶν θνητῶν [[τῶν [μὲν] ἄλλων ζῴων]] [τὸ ἔμψυχον ἔχει].", "st": "X.12"}, {"sp": "N", "t": "οὐκέτι δὲ μόνον οὐκ ἀγαθὸς, ἀλλὰ καὶ κακός, ὡς θνητός.", "st": "X.12b"}, {"sp": "N", "t": "ὁ μὲν γὰρ κόσμος οὐκ ἀγαθός, ὡς κινητός, οὐ κακὸς δέ, ὡς ἀθάνατος·", "st": "X.12c"}, {"sp": "N", "t": "ὁ δὲ ἄνθρωπος καὶ ὡς κινητὸς ⟨οὐκ ἀγαθός⟩, καὶ ὡς θνητὸς κακός.", "st": "X.12d"}, {"sp": "N", "t": "ψυχὴ δὲ ἀνθρώπου ὀχεῖται τὸν τρόπον τοῦτον, ὁ νοῦς [ἐν τῷ λόγῳ, ὁ λόγος] ἐν τῇ ψυχῇ, ἡ δὲ ψυχὴ ἐν τῷ πνεύματι·", "st": "X.13"}, {"sp": "N", "t": "τὸ ⟨δὲ⟩ πνεῦμα, διῆκον διὰ ⟨τῶν⟩ [φλεβῶν καὶ] ἀρτηριῶν [καὶ] ⟨μετὰ τοῦ⟩ αἵματος, κινεῖ τὸ [ζῷον] ⟨σῶμα⟩ καὶ ὥσπερ φόρτον τινὰ βαστάζει.", "st": "X.13b"}, {"sp": "N", "t": "διὸ καί τινες τὴν ψυχὴν αἷμα ἐνόμισαν εἶναι, σφαλλόμενοι τῆς φύσεως, οὐκ εἰδότες ὅτι πρῶτον δεῖ τοῦ πνεύματος ἀναχωρήσαντος εἰς ⟨ἐξελθεῖν⟩ τὴν ψυχήν, καὶ τότε, ⟨τὸ περιέχον⟩, τὸ αἷμα παγῆναι κατὰ τὰς φλέβας, καὶ τὰς ἀρτηρίας κενωθείσας [τὸ ζῷον] καταλ[ε]ιπεῖν. καὶ τοῦτο ἔστιν ὁ θάνατος τοῦ σώματος.", "st": "X.13c"}, {"sp": "N", "t": "ἐκ μιᾶς δὲ ἀρχῆς τὰ πάντα ἤρτηται, ἡ δὲ ἀρχὴ ἐκ τοῦ ἑνὸς καὶ μόνου. καὶ ἡ μὲν ἀρχὴ κινεῖται, ἵνα πάντων ἀρχὴ γένηται· τὸ δὲ ἓν μόνον ἕστηκεν, καὶ οὐ κινεῖται.", "st": "X.14"}, {"sp": "N", "t": "[καὶ] τρία τοίνυν ταῦτα, ὁ θεός [καὶ πατὴρ καὶ τὸ ἀγαθόν], καὶ ὁ κόσμος, καὶ ὁ ἄνθρωπος·", "st": "X.14b"}, {"sp": "N", "t": "καὶ τὸν μὲν κόσμον ὁ θεὸς ἔχει, τὸν δὲ ἄνθρωπον ὁ κόσμος. καὶ γίνεται ὁ μὲν κόσμος τοῦ θεοῦ υἱός, ὁ δὲ ἄνθρωπος τοῦ κόσμου ⟨υἱός, καὶ τοῦ θεοῦ⟩ ὥσπερ ἔγγονος.", "st": "X.14c"}, {"sp": "N", "t": "οὐκ ἄρ⟨α⟩ ἀγνοεῖ τὸν ἄνθρωπον ὁ θεός, ἀλλὰ καὶ πάνυ γνωρίζει, καὶ θέλει γνωρίζεσθαι.", "st": "X.15"}, {"sp": "N", "t": "τοῦτο μόνον σωτήριον ἀνθρώπῳ ἐστίν, ἡ γνῶσις τοῦ θεοῦ· αὕτη εἰς τὸν Ὄλυμπον ἀνάβασις·", "st": "X.15b"}, {"sp": "N", "t": "τούτῳ μόνῳ ἀγαθὴ ψυχή. ⟨…⟩ καὶ οὐδέποτε ἀγαθὴ ⟨μένει⟩, κακὴ δὲ γίνεται κατ’ ἀνάγκην γίνεται.", "st": "X.15c"}, {"sp": "N", "t": "— Πῶς τοῦτο λέγεις, ὦ τρισμέγιστε; Ψυχὴν παιδὸς θέασαι, ὦ τέκνον, [ε]αὐτὴν διάλυσιν αὑτῆς μηδέπω ἐπιδεχομένην, τοῦ σώματος αὐτῆς ἔτι ὀλίγ⟨ου⟩ ὄν⟨τος⟩ καὶ μηδέπω τὸ πᾶν ὠγκωμένου, πῶς καλὴ[ν μέν] βλέπειν πανταχοῦ, μηδέπω[τε δὲ] τεθολωμένη[ν] ὑπὸ τῶν τοῦ σώματος παθῶν, ἔτι σχεδὸν ἠρτημένη τῆς τοῦ κόσμου ψυχῆς.", "st": "X.15d"}, {"sp": "N", "t": "ὅταν δὲ ὀγκωθῇ τὸ σῶμα, καὶ κατασπάσῃ αὐτὴν εἰς τοὺς [τοῦ σώματος] ὄγκους, διαλύσασα δὲ ἑαυτὴν ἐγγεννᾷ λήθην [καὶ] τοῦ καλοῦ καὶ ἀγαθοῦ, οὐ⟨κέτι τούτου⟩ μεταλαμβάνει, ⟨τ⟩ῇ δὲ λήθῃ κακὴ γίνεται.", "st": "X.15e"}, {"sp": "N", "t": "τὸ δὲ [αὐτὸ] ⟨ἐναντίον⟩ συμβαίνει [καὶ] τοῖς τοῦ σώματος ἐξιοῦσιν.", "st": "X.16"}, {"sp": "N", "t": "ἀναδραμοῦσα γὰρ ἡ ψυχὴ εἰς ⟨τὰ⟩ ἑαυτῆς ⟨τοῦ πνεύματος χωρίζεται, καὶ ὁ νοῦς τῆς ψυχῆς⟩· συστέλλεται τὸ πνεῦμα εἰς τὸ αἷμα, ἡ δὲ ψυχὴ εἰς τὸ πνεῦμα ὁ δὲ νοῦς καθαρὸς γενόμενος τῶν ἐνδυμάτων, θεῖος ὢν φύσει, σώματος πυρίνου ⟨ἐπι⟩λαβόμενος περιπολεῖ πάντα τόπον, καταλιπὼν τὴν ψυχὴν κρίσει καὶ τῇ κατ’ ἀξίαν δίκῃ.", "st": "X.16b"}, {"sp": "N", "t": "— Πῶς τοῦτο λέγεις, ὦ πάτερ, ⟨ὅτι⟩ ὁ νοῦς τῆς ψυχῆς χωρίζεται [καὶ ἡ ψυχὴ τοῦ πνεύματος], [σοῦ εἰπόντος ἔνδυμα εἶναι τοῦ μὲν νοῦ τὴν ψυχήν, τῆς δὲ ψυχῆς τὸ πνεῦμα];", "st": "X.16c"}, {"sp": "N", "t": "— Συννοεῖν δεῖ, ὦ τέκνον, τὸν ἀκούοντα τῷ λέγοντι [καὶ συμπνεῖν], καὶ ὀξυτέραν ἔχειν τὴν ἀκοὴν τῆς τοῦ λέγοντος φωνῆς.", "st": "X.17"}, {"sp": "N", "t": "ἡ σύνθεσις [τῶν ἐνδυμάτων] τούτων ἐν σώματι γηίνῳ γίνεται. ἀδύνατον γὰρ τὸν νοῦν ἐν γηίνῳ σώματι γυμνὸν αὐτὸν καθ’ ἑαυτὸν ἑδράσ⟨ασθ⟩αι·", "st": "X.17b"}, {"sp": "N", "t": "οὔτε γὰρ τὸ γήινον σῶμα δυνατόν ἐστι τηλικαύτην ἀθανασίαν ἐνεγκεῖν, οὔτε τὴν τοσαύτην ἀρετὴν ἀνέχεσθαι συγχρωτιζόμενον αὑτῇ παθητὸν σῶμα. ἔλαβεν οὖν ὥσπερ περιβολὴν τὴν ψυχήν· ἡ δὲ ψυχή.", "st": "X.17c"}, {"sp": "N", "t": "καὶ αὐτὴ θεία τις οὖσα, καθαπερεὶ περι⟨βολῇ⟩ τῷ πνεύματι χρῆται, τὸ δὲ πνεῦμα τὸ [ζῷον] ⟨σῶμα⟩ διοικεῖ·", "st": "X.17d"}, {"sp": "N", "t": "ὅταν οὖν ὁ νοῦς ἀπαλλαγῇ τοῦ γηίνου σώματος, τὸν ἴδιον εὐθὺς ἐνεδύσατο χιτῶνα, τὸν πύρινον, ὃν οὐκ ἠδύνατο ἔχων εἰς τὸ γήινον σῶμα κατοικῆσαι.", "st": "X.18"}, {"sp": "N", "t": "γῆ γὰρ πῦρ οὐ βαστάζει· πᾶσα γὰρ φλέγεται καὶ ὑπὸ ὀλίγου σπινθῆρος· καὶ διὰ τοῦτο καὶ τὸ ὕδωρ περικέχυται τῇ γῇ, ὥσπερ ἔρυμα καὶ τεῖχος ἀντέχον πρὸς τὴν τοῦ πυρὸς φλόγα.", "st": "X.18b"}, {"sp": "N", "t": "νοῦς δέ, ὀξύτατος ὢν πάντων τῶν [θείων] νοη[μα]τῶν, καὶ τὸ ὀξύτατον πάντων τῶν στοιχείων ἔχει σῶμα, τὸ πῦρ.", "st": "X.18c"}, {"sp": "N", "t": "δημιουργὸς γὰρ ὢν [πάντων] ὁ νοῦς ὀργάνῳ τῷ πυρὶ πρὸς τὴν δημιουργίαν χρῆται. καὶ ὁ μὲν τοῦ παντὸς τῶν πάντων ⟨δημιουργός⟩, ὁ δὲ τοῦ ἀνθρώπου τῶν ἐπιγείων μόνον·", "st": "X.18d"}, {"sp": "N", "t": "γυμνὸς γὰρ ὢν τοῦ πυρὸς ὁ ἐν ἀνθρώπῳ νοῦς ἀδυνατεῖ τὰ θεῖα δημιουργεῖν, ἀνθρώπινος ὢν τῇ οἰκήσει.", "st": "X.18e"}, {"sp": "N", "t": "ψυχὴ δὲ ἀνθρωπίνη, οὐ πᾶσα μέν, ἡ δὲ εὐσεβής, δαιμονία τίς ἐστι καὶ θεία·", "st": "X.19"}, {"sp": "N", "t": "καὶ ἡ τοιαύτη ψυχή, μετὰ τὸ ἀπαλλαγῆναι τοῦ σώματος τὸν τῆς εὐσεβείας ἀγῶνα ἀγωνισαμένη,<br>— ἀγὼν δὲ εὐσεβείας τὸ γνῶναι τὸν θεὸν καὶ μηδένα ἀνθρώπων ἀδικῆσαι,", "st": "X.19b"}, {"sp": "N", "t": "— ὅλη νοῦς γίνεται· ⟨καὶ⟩ ἡ δὲ ἀσεβὴς ψυχὴ μένει ἐπὶ τῆς ἰδίας οὐσίας, ὑφ’ ἑαυτῆς κολαζομένη, καὶ γήινον σῶμα ζητοῦσα εἰς ὃ εἰσέλθῃ.", "st": "X.19c"}, {"sp": "N", "t": "ἀνθρώπινον δέ· ἄλλο γὰρ σῶμα οὐ χωρεῖ ἀνθρωπίνην ψυχήν. οὐδὲ θέμις ἐστὶν εἰς ἀλόγου ζῴου σῶμα ψυχὴν ἀνθρωπίνην καταπεσεῖν· θεοῦ γὰρ νόμος οὗτος, φυλάσσειν ψυχὴν ἀνθρωπίνην ἀπὸ τῆς τοιαύτης ὕβρεως.", "st": "X.19d"}, {"sp": "N", "t": "— Πῶς οὖν κολάζεται, ὦ πάτερ, ἀνθρωπίνη ψυχή;", "st": "X.20"}, {"sp": "N", "t": "— Καὶ τίς ἐστι μείζων κόλασις [ἀνθρωπίνης ψυχῆς], ὦ τέκνον, ἢ ἡ ἀσέβεια; ποῖον πῦρ τοσαύτην φλόγα ἔχει ὅσην ἡ ἀσέβεια; ποῖον δὲ δακετὸν θηρίον ⟨τοσοῦτον ἰσχύει⟩ [ὥστε] λυμᾶναι ⟨τὸ⟩ σῶμα, ὅσον αὐτὴν τὴν ψυχὴν ἡ ἀσέβεια;", "st": "X.20b"}, {"sp": "N", "t": "ἢ οὐχ ὁρᾷς ὅσα κακὰ πάσχει ψυχὴ ἡ ἀσεβής, βοώσης αὐτῆς καὶ κεκραγυίας καίομαι, φλέγομαι·", "st": "X.20c"}, {"sp": "N", "t": "τί εἴπω, τί ποιήσω οὐκ οἶδα· διεσθίομαι ἡ κακοδαίμων ὑπὸ τῶν κατεχόντων με κακῶν.", "st": "X.20d"}, {"sp": "N", "t": "[οὔτε βλέπω οὔτε ἀκούω.] αὗται αἱ φωναὶ οὐ κολαζομένης εἰσὶ ψυχῆς; ἢ ὡς οἱ πολλοὶ δοκοῦσι καὶ σὺ δοξάζεις, ὦ τέκνον, ὅτι ψυχὴ ἐξελθοῦσα τοῦ σώματος θηριάζεται;", "st": "X.20e"}, {"sp": "N", "t": "ὅπερ ἐστὶ πλάνη μεγίστη. ψυχὴ γὰρ κολάζεται τοῦτον τὸν τρόπον.", "st": "X.21"}, {"sp": "N", "t": "ὁ γὰρ νοῦς, ὅταν δαίμων γένηται, πυρίνου τυχεῖν σώματος τέτακται πρὸς τὰς τοῦ θεοῦ ὑπηρεσίας, [καὶ] εἰσδὺς εἰς τὴν ἀσεβῆ ψυχήν, αἰκίζεται αὐτὴν ταῖς τῶν ἁμαρτημάτων μάστιξιν, ὑφ’ ὧν μαστιζομένη [ἀσεβὴς ψυχὴ] ⟨κολάζεται⟩·", "st": "X.21b"}, {"sp": "N", "t": "τρέπεται ⟨γὰρ⟩ ἐπὶ φόνους καὶ ὕβρεις καὶ βλασφημίας καὶ βίας ποικίλας δι’ ὧν ἄνθρωποι ἀδικοῦνται.", "st": "X.21c"}, {"sp": "N", "t": "εἰς δὲ τὴν εὐσεβῆ ψυχὴν ὁ νοῦς ἐμβὰς ὁδηγεῖ αὐτὴν ἐπὶ τὸ τῆς γνώσεως φῶς· ἡ δὲ τοιαύτη ψυχὴ κόρον οὐδέποτε ἴσχει ⟨τὸν θεὸν⟩ ὑμνοῦσα εὐφημοῦσά τε, ⟨καὶ⟩ πάντας ἀνθρώπους καὶ λόγοις καὶ ἔργοις πάντα ε’υ ποιοῦσα, μιμουμένη αὑτῆς τὸν πατέρα.", "st": "X.21d"}, {"sp": "N", "t": "διό, ὦ τέκνον, εὐχαριστοῦντα τῷ θεῷ δεῖ εὔχεσθαι καλοῦ τοῦ νοῦ τυχεῖν.", "st": "X.22"}, {"sp": "N", "t": "εἰς μὲν οὖν τὸ κρεῖττον ψυχὴ μεταβαίνει· εἰς δὲ τὸ ἔλαττον ἀδύνατον.", "st": "X.22b"}, {"sp": "N", "t": "κοινωνία δέ ἐστι ψυχῶν· καὶ κοινωνοῦσι⟨ν⟩ μὲν αἱ τῶν θεῶν ταῖς τῶν ἀνθρώπων, αἱ δὲ τῶν ἀνθρώπων ταῖς τῶν ἀλόγων.", "st": "X.22c"}, {"sp": "N", "t": "ἐπιμελοῦνται δὲ οἱ κρείττονες τῶν ἐλαττόνων, θεοὶ μὲν ἀνθρώπων, ἄνθρωποι δὲ τῶν ἀλόγων [ζῴων], ὁ δὲ θεὸς πάντων· πάντων γὰρ οὗτος κρείττων [καὶ πάντα αὐτοῦ ἐλάττονα].", "st": "X.22d"}, {"sp": "N", "t": "ὁ μὲν οὖν κόσμος ὑπόκειται τῷ θεῷ, ὁ δὲ ἄνθρωπος τῷ κόσμῳ, τὰ δὲ ἄλογα τῷ ἀνθρώπῳ· ὁ δὲ θεὸς ὑπὲρ πάντα καὶ περὶ πάντα.", "st": "X.22e"}, {"sp": "N", "t": "καὶ τοῦ μὲν θεοῦ καθάπερ ἀκτῖνες αἱ ἐνέργειαι· τοῦ δὲ κόσμου [ἀκτῖνες] αἱ φύσεις· τοῦ δὲ ἀνθρώπου, αἱ τέχναι καὶ ἐπιστῆμαι.", "st": "X.22f"}, {"sp": "N", "t": "καὶ αἱ μὲν ἐνέργειαι, διὰ τοῦ κόσμου ἐνεργοῦσ⟨α⟩ι, καὶ ἐπὶ τὸν ἄνθρωπον ⟨διήκουσι⟩ διὰ τῶν τοῦ κόσμου φυσικῶν ἀκτίνων· αἱ δὲ φύσεις διὰ τῶν στοιχείων. [οἱ δὲ ἄνθρωποι διὰ τῶν τεχνῶν καὶ ἐπιστημῶν.]", "st": "X.22g"}, {"sp": "N", "t": "καὶ αὕτη ἡ τοῦ παντός ἐστι διοίκησις, ἠρτημένων ⟨πάντων⟩ ἐκ τῆς ἑνὸς ⟨τοῦ θεοῦ⟩ φύσεως, καὶ διοικουμένων δι’ ἑνὸς τοῦ νοῦ· ⟨οὗ⟩ οὐδέν ἐστι θειότερον καὶ ἐνεργέστερον, καὶ ἑνωτικώτερον ἀνθρώπων μὲν πρὸς θεούς, θεῶν δὲ πρὸς ἀνθρώπους.", "st": "X.23"}, {"sp": "N", "t": "οὗτός ἐστιν ὁ ἀγαθὸς δαίμων· μακαρία ψυχὴ ἡ τούτου πλήρης, κακοδαίμων δὲ [ψυχὴ] ἡ τούτου κενή.", "st": "X.23b"}, {"sp": "N", "t": "— Πῶς τοῦτο πάλιν λέγεις, ὦ πάτερ;", "st": "X.23c"}, {"sp": "N", "t": "— Οἴει οὖν ὦ τέκνον, ὅτι πᾶσα ψυχὴ νοῦν ἔχει; [τὸν ἀγαθόν· περὶ γὰρ τούτου νῦν ὁ λόγος, οὐ τοῦ ὑπηρετικοῦ περὶ οὗ ἔμπροσθεν εἰρήκαμεν, τοῦ καταπεμπομένου ὑπὸ τῆς δίκης.]", "st": "X.23d"}, {"sp": "N", "t": "ψυχὴ γὰρ χωρὶς νοῦ οὔτε τι εἰπεῖν οὔτ’ ἔρξαι δύναται. πολλάκις γὰρ ἐξίσταται ὁ νοῦς τῆς ψυχῆς· καὶ ἐν ἐκείνῃ τῇ ὥρᾳ οὔτε βλέπει ἡ ψυχὴ οὔτε ἀκούει, ἀλλ’ ἀλόγῳ ζῴῳ ἔοικε· ψυχὴ γὰρ χωρὶς νοῦ οὔτε τι εἰπεῖν οὔτ’ ἔρξαι δύναται. τηλικαύτη δύναμίς ἐστι τοῦ νοῦ.", "st": "X.24"}, {"sp": "N", "t": "ἀλλ’ οὐδὲ νωθρᾶς ψυχῆς ἀνέχεται, ἀλλὰ καταλείπει τὴν [ἐν] τῷ σώματι προσηρτημένην καὶ ὑπ’ αὐτοῦ ἀγχομένην κάτω.", "st": "X.24b"}, {"sp": "N", "t": "ἡ δὲ τοιαύτη ψυχή, ὦ τέκνον, νοῦν οὐχ ἔχει· ὅθεν οὐδ’ ἄνθρωπον ἡγεῖσθαι δεῖ τὸν τοιοῦτον. ὁ γὰρ ἄνθρωπος ζῷόν ἐστι θεῖον, καὶ τοῖς ἄλλοις ζῴοις οὐ συγκρίνεται τοῖς ἐπιγείοις, ἀλλὰ τοῖς ἐν οὐρανῷ [ἄνω λεγομένοις] θεοῖς·", "st": "X.24c"}, {"sp": "N", "t": "μᾶλλον δέ, εἰ χρὴ τολμήσαντας εἰπεῖν τὸ ἀληθές, καὶ ὑπὲρ ἐκείνους ἐστὶν ὁ ὄντως ἄνθρωπος, ἢ πάντως γε ἰσοδυναμοῦσιν ἀλλήλοις.", "st": "X.24d"}, {"sp": "N", "t": "οὐδεὶς μὲν γὰρ τῶν οὐρανίων θεῶν ἐπὶ γῆν κατελεύσεται, οὐρανοῦ τὸν ὅρον καταλιπών· ὁ δὲ ἄνθρωπος καὶ εἰς τὸν οὐρανὸν ἀναβαίνει, καὶ μετρεῖ αὐτὸν [καὶ οἶδε ποῖα μέν ἐστιν αὐτοῦ ὑψηλά, ποῖα δὲ ταπεινά, καὶ τὰ ἄλλα πάντα ἀκριβῶς μανθάνει]· καὶ τὸ πάντων μεῖζον, οὐδὲ τὴν γῆν καταλιπὼν ἄνω γίνεται·", "st": "X.25"}, {"sp": "N", "t": "τοσοῦτον τὸ μέγεθός ἐστιν αὐτῷ τῆς ἐκτάσεως.", "st": "X.25b"}, {"sp": "N", "t": "διὸ τολμητέον εἰπεῖν τὸν μὲν ἄνθρωπον ἐπίγειον εἶναι θνητὸν θεόν, τὸν δὲ οὐράνιον θεὸν ἀθάνατον ἄνθρωπον.", "st": "X.25c"}, {"sp": "N", "t": "διόπερ διὰ τούτων τὰ πάντα διοικεῖται τῶν δύο, κόσμου καὶ ἀνθρώπου, ὑπὸ δὲ τοῦ ἑνὸς ⟨θεοῦ⟩ τὰ πάντα.", "st": "X.25d"}, {"sp": "HDR", "t": "Νοῦς πρὸς Ἑρμῆν"}, {"sp": "N", "t": "[[κατάσχες οὖν τοῦ λόγου, ὦ τρισμέγιστε Ἑρμῆ, καὶ μέμνησο τῶν λεγομένων. ὡς δέ μοι ἐπῆλθεν εἰπεῖν οὐκ ὀκνήσω.", "st": "XI.1"}, {"sp": "N", "t": "ἐπεὶ πολλὰ πολλῶν καὶ ταῦτα διάφορα περὶ τοῦ παντὸς καὶ τοῦ θεοῦ εἰπόντων ἐγὼ τὸ ἀληθὲς οὐκ ἔμαθον, σύ μοι περὶ τούτου, δέσποτα, διασάφησον· σοὶ γὰρ ἂν καὶ μόνῳ πιστεύσαιμι τὴν περὶ τούτου φανέρωσιν.", "st": "XI.1b"}, {"sp": "N", "t": "[ὁ χρόνος.] ἄκουε, ὦ τέκνον, ὡς ἔχει ὁ θεὸς καὶ τὸ πᾶν.]]", "st": "XI.1c"}, {"sp": "N", "t": "⟨ὁ⟩ θεός, ὁ αἰών, ὁ κόσμος, ὁ χρόνος, ἡ γένεσις.", "st": "XI.2"}, {"sp": "N", "t": "ὁ θεὸς ⟨τὸν⟩ αἰῶνα ποιεῖ, ὁ αἰὼν δὲ τὸν κόσμον, ὁ κόσμος δὲ τὸν χρόνον, ὁ χρόνος δὲ τὴν γένεσιν.", "st": "XI.2b"}, {"sp": "N", "t": "τοῦ δὲ θεοῦ [ὥσπερ] οὐσία ἐστὶ τὸ ἀγαθόν, [τὸ καλόν, ἡ εὐδαιμονία, ἡ σοφία,] τοῦ δὲ αἰῶνος, ἡ ταυτότης, τοῦ δὲ κόσμου, ἡ τάξις, τοῦ δὲ χρόνου, ἡ μεταβολή, τῆς δὲ γενέσεως, ἡ ζωή [καὶ ὁ θάνατος].", "st": "XI.2c"}, {"sp": "N", "t": "ἐνέργειαι δὲ τοῦ θεοῦ νοῦς καὶ ψυχή, τοῦ δὲ αἰῶνος, ἀθανασία καὶ διαμονή, τοῦ δὲ κόσμου, ἀποκατάστασις καὶ ἀνταποκατάστασις, τοῦ δὲ χρόνου, αὔξησις καὶ μείωσις, τῆς δὲ γενέσεως, ποιότης ⟨καὶ ποσότης⟩.", "st": "XI.2d"}, {"sp": "N", "t": "ὁ οὖν αἰὼν ἐν τῷ θεῷ, ὁ δὲ κόσμος ἐν τῷ αἰῶνι, ὁ δὲ χρόνος ἐν τῷ κόσμῳ, ἡ δὲ γένεσις ἐν τῷ χρόνῳ.", "st": "XI.2e"}, {"sp": "N", "t": "καὶ ὁ μὲν αἰὼν ἕστηκε περὶ τὸν θεόν, ὁ δὲ κόσμος κινεῖται ἐν τῷ αἰῶνι, ὁ δὲ χρόνος περαιοῦται ἐν τῷ κόσμῳ, ἡ δὲ γένεσις γίνεται ἐν τῷ χρόνῳ.", "st": "XI.2f"}, {"sp": "N", "t": "πηγὴ μὲν οὖν πάντων ὁ θεός, [οὐσία δὲ ὁ αἰών, ὕλη δὲ ὁ κόσμος,] δύναμις δὲ τοῦ θεοῦ ὁ αἰών, ἔργον δὲ τοῦ αἰῶνος ὁ κόσμος, γενόμενος οὔποτε, καὶ ἀεὶ γινόμενος ὑπὸ τοῦ αἰῶνος.", "st": "XI.3"}, {"sp": "N", "t": "διὸ οὐδὲ φθαρήσεταί ποτε· αἰὼν γὰρ ἄφθαρτος. οὐδὲ ἀπολεῖταί τι τῶν ἐν τῷ κόσμῳ, τοῦ κόσμου ὑπὸ τοῦ αἰῶνος ἐμπεριεχομένου.", "st": "XI.3b"}, {"sp": "N", "t": "[ἡ δὲ τοῦ θεοῦ σοφία ⟨οὐσία⟩ τί[ς] ἐστι;", "st": "XI.3c"}, {"sp": "N", "t": "τὸ ἀγαθὸν καὶ τὸ καλόν.] [καὶ ἡ εὐδαιμονία καὶ [ἡ] πᾶσα ἀρετή.]", "st": "XI.3d"}, {"sp": "N", "t": "καὶ ὁ αἰὼν κοσμεῖ [οὖν] τὴν ⟨ὕλην⟩, ἀθανασίαν καὶ διαμονὴν ἐνθεὶς τῇ ὕλῃ·", "st": "XI.4"}, {"sp": "N", "t": "[ἡ γὰρ ἐκείνης γένεσις] ἤρτηται ἐκ τοῦ αἰῶνος, καθάπερ καὶ ὁ αἰὼν ἐκ τοῦ θεοῦ·", "st": "XI.4b"}, {"sp": "N", "t": "ἡ γὰρ γένεσις [καὶ ὁ χρόνος ἐν οὐρανῷ καὶ ἐν γῇ εἰσιν ὄντες] διφυής, ἐν μὲν οὐρανῷ ἀμεταβλήτων καὶ ἀφθάρτων, ἐν δὲ γῇ μεταβλητῶν καὶ φθαρτῶν.", "st": "XI.4c"}, {"sp": "N", "t": "⟨ὁ κόσμος οὖν⟩ καὶ τοῦ μὲν αἰῶνος †ἡ ψυχὴ† ὁ θεός, τοῦ δὲ κόσμου ὁ αἰών [τῆς δὲ γῆς ὁ οὐρανός].", "st": "XI.4d"}, {"sp": "N", "t": "[καὶ ὁ μὲν θεὸς ἐν τῷ νῷ, ὁ δὲ νοῦς ἐν τῇ ψυχῇ, ἡ δὲ ψυχὴ ἐν τῇ ὕλῃ.] [πάντα δὲ ταῦτα διὰ τοῦ αἰῶνος.] τὸ δὲ πᾶν τοῦτο σῶμα, ἐν ᾧ τὰ πάντα ἐστὶ σώματα, ⟨ψυχῆς πλῆρές ἐστιν·", "st": "XI.4e"}, {"sp": "N", "t": "ἡ δὲ⟩ ψυχὴ πλήρης τοῦ νοῦ, καὶ ⟨ὁ νοῦς⟩ τοῦ θεοῦ.", "st": "XI.4f"}, {"sp": "N", "t": "⟨ψυχὴ δὲ⟩ ἐντὸς μὲν αὐτὸ πληροῖ, ἐκτὸς δὲ περιλαμβάνει, ζωοποιοῦσα τὸ πᾶν, ἐκτὸς μὲν τοῦτο τὸ μέγα καὶ τέλειον ζῷον [τὸν κόσμον], ἐντὸς δὲ πάντα τὰ ζῷα, καὶ ἄνω μὲν ἐν τῷ οὐρανῷ διαμένουσα ⟨ἐν⟩ τῇ ταυτότητι, κάτω δὲ ἐπὶ τῆς γῆς ⟨ἅμα⟩ τῇ γενέσει μεταβάλλουσα.", "st": "XI.4g"}, {"sp": "N", "t": "συνέχει δὲ τοῦτο ⟨τὸ πᾶ⟩ν ὁ αἰών,<br>— εἴτε [δι’] ἀνάγκην, εἴτε πρόνοιαν, εἴτε φύσιν, [καὶ] εἴ⟨τε⟩ τι ἄλλο οἴεται ἢ οἰηθήσεταί τις,<br>— τοῦτο ἔστι [πᾶ]ν, ὁ θεὸς ἐνεργῶν.", "st": "XI.5"}, {"sp": "N", "t": "ἡ δὲ ἐνέργεια ⟨τοῦ⟩ θεοῦ δυνάμει [οὖσα] ἀνυπέρβλητος, ᾗ οὔτε τὰ ἀνθρώπεια οὔτε τὰ θεῖα παραβάλλοι ἄν τις.", "st": "XI.5b"}, {"sp": "N", "t": "διό, ⟨ὦ⟩ Ἑρμῆ, μή[δεπο]τε τῶν κάτω μήτε τῶν ἄνω ὅμοιόν τι ἡγήσῃ τῷ θεῷ· ἐπεὶ τῆς ἀληθείας ἐκπεσῇ· οὐδὲν γὰρ ὅμοιον τῷ [ἀνομοίῳ καὶ] μόνῳ καὶ ἑνί.", "st": "XI.5c"}, {"sp": "N", "t": "[καὶ] μηδὲ ἄλλῳ τινὶ ἡγήσῃ τῆς δυνάμεως ἐκχωρεῖν· τίς γὰρ κατ’ ἐκεῖνον; ⟨τίς ἄλλος αἴτιος⟩ [εἴτε] ζωῆς, καὶ ἀθανασίας καὶ μεταβολῆς ποιητής; τί δὲ αὐτοῦ ἄλλο ⟨ἔργον ἢ⟩ τὸ ποιεῖν;", "st": "XI.5d"}, {"sp": "N", "t": "οὐ γὰρ ἀργὸς ὁ θεός· ἐπεὶ πάντα ἂν ἦν ἀργά.", "st": "XI.5e"}, {"sp": "N", "t": "ἅπαντα γὰρ πλήρη τοῦ θεοῦ. ἀλλ’ οὐδὲ ἐν τῷ κόσμῳ ἐστὶν ἀργία οὐδαμοῦ [οὐδὲ ἔν τινι ἄλλῳ]· ἀργία γὰρ ὄνομα κενόν ἐστι, καὶ τοῦ ποιοῦντος καὶ τοῦ γινομένου.", "st": "XI.5f"}, {"sp": "N", "t": "πάντα δὲ δεῖ γίνεσθαι καὶ ἀεὶ καὶ καθ’ ἕκαστον τόπον [ῥοπήν].", "st": "XI.6"}, {"sp": "N", "t": "ὁ γὰρ ποιῶν ἐν πᾶσίν ἐστιν, οὐκ ἔν τινι ἱδρυμένος, οὐδὲ ἕν τι ποιῶν, ἀλλὰ πάντα, ⟨πανταχοῦ⟩.", "st": "XI.6b"}, {"sp": "N", "t": "δύναμις γὰρ ὢν ἐνεργὴς οὐκ αὐτάρκης ἐστὶ τοῖς γινομένοις, ἀλλὰ τὰ γινόμενα ὑπ’ αὐτῷ.", "st": "XI.6c"}, {"sp": "N", "t": "θέασαι δὴ δι’ ἐμοῦ τὸν κόσμον ὑποκείμενον τῇ σῇ ὄψει, [τό τε κάλλος αὐτοῦ ἀκριβῶς κατανόησον,] σῶμα [μὲν] ἀκήρατον, καὶ οὗ παλαιότερον οὐδὲν ἐστ[α]ι, διὰ παντὸς δὲ ἀκμαῖον καὶ νέον [καὶ μᾶλλον ἀκμαιότερον].", "st": "XI.6d"}, {"sp": "N", "t": "ἴδε καὶ τοὺς ὑποκειμένους ἑπτὰ κόσμους, κεκοσμημένους τάξει αἰωνίῳ, καὶ δρόμῳ διαφόρῳ τὸν αἰῶνα ἀναπληροῦντας.", "st": "XI.7"}, {"sp": "N", "t": "φωτὸς δὲ πάντα πλήρη, πῦρ δὲ οὐδαμοῦ ⟨...· τ⟩ῇ γὰρ φιλίᾳ τῶν ἐναντίων καὶ ⟨τ⟩ῇ συγκράσει τῶν ἐναντίων [καὶ] τῶν ἀνομοίων ⟨τὸ πῦρ⟩ φῶς γέγονε, καταλαμπόμενον ὑπὸ τῆς τοῦ [θεοῦ] ⟨ἡλίου⟩ ἐνεργείας, ⟨τοῦ⟩ παντὸς ἀγαθοῦ γεννήτορος, καὶ πάσης τάξεως ἄρχοντος, καὶ ἡγεμόνος τῶν ἑπτὰ κόσμων.", "st": "XI.7b"}, {"sp": "N", "t": "σελήνην ⟨ἴ⟩δε, ἐκείνων πρόδρομον πάντων, ὄργανον τῆς φύσεως, τὴν κάτω ὕλην μεταβάλλουσαν·", "st": "XI.7c"}, {"sp": "N", "t": "τήν τε γῆν, μέσην τοῦ παντὸς, ὑποστάθμην τοῦ καλοῦ κόσμου ἱδρυμένην, τροφὸν καὶ τιθήνην τῶν ἐπιγείων.", "st": "XI.7d"}, {"sp": "N", "t": "θέασαι δὲ καὶ τὸ πλῆθος τῶν ἀθανάτων ζῴων ὅσον ἐστί, καὶ τὸ τῶν θνητῶν, μέσην δὲ ἀμφοτέρων [τῶν τε ἀθανάτων καὶ τῶν θνητῶν] τὴν σελήνην περιπορευομένην.", "st": "XI.7e"}, {"sp": "N", "t": "πάντα δὲ πλήρη ψυχῆς, καὶ πάντα κινούμενα, τὰ μὲν περὶ τὸν οὐρανόν, τὰ δὲ περὶ τὴν γῆν. [καὶ μήτε τὰ δεξιὰ ἐπὶ τὰ ἀριστερὰ μήτε τὰ ἀριστερὰ ἐπὶ τὰ δεξιά, μήτε τὰ ἄνω κάτω μήτε τὰ κάτω ἄνω.]", "st": "XI.8"}, {"sp": "N", "t": "καὶ ὅτι πάντα ταῦτα γεννητά, ὦ φίλτατε Ἑρμῆ, οὐκέτι ἐμοῦ χρῄζεις μαθεῖν. καὶ γὰρ σώματά ἐστι, καὶ ψυχὴν ἔχει, ⟨ᾗ⟩ καὶ κινεῖται·", "st": "XI.8b"}, {"sp": "N", "t": "ταῦτα δὲ εἰς ἓν συνελθεῖν ἀδύνατον χωρὶς τοῦ συναγόντος. δεῖ οὖν ⟨τοιοῦτόν⟩ τινα εἶναι, τοῦτον καὶ πάντως ἕνα.", "st": "XI.8c"}, {"sp": "N", "t": "[ἐν] διαφόρων γὰρ καὶ πολλῶν οὐσῶν τῶν κινήσεων, καὶ τῶν σωμάτων οὐχ ὁμοίων, μιᾶς δὲ κατὰ πάντων τάξεως τετα[γ]μένης, ἀδύνατον δύο ἢ πλείους ποιητὰς εἶναι.", "st": "XI.9"}, {"sp": "N", "t": "μία γὰρ ἐπὶ πολλῶν οὐ τηρεῖται τάξις· ζῆλος δὲ τοῖς πολλοῖς παρέψεται, ⟨…⟩ τοῦ κρείττονος, καὶ ἐριοῦσι.", "st": "XI.9b"}, {"sp": "N", "t": "καὶ εἰ ἕτερος ἦν ὁ ποιητὴς τῶν μεταβλητῶν [ζῴων] καὶ θνητῶν, ἐπεθύμησεν ἂν καὶ ἀθανάτους ποιῆσαι, ὥσπερ καὶ ὁ τῶν ἀθανάτων θνητούς.", "st": "XI.9c"}, {"sp": "N", "t": "φέρε δέ, εἰ καὶ δύο εἰσί, μιᾶς οὔσης τῆς ὕλης καὶ μιᾶς τῆς ψυχῆς, παρὰ τίνι [ἂν] αὐτῶν ἡ χορηγία [τῆς ποιήσεως]; εἰ δὲ καὶ παρὰ ἀμφοτέροις, παρὰ τίνι τὸ πλεῖον μέρος;", "st": "XI.9d"}, {"sp": "N", "t": "οὕτω δὲ νόει, ὡς παντὸς σώματος ζῶντος ἐξ ὕλης καὶ ψυχῆς τὴν σύστασιν ἔχοντος, καὶ τοῦ ἀθανάτου καὶ τοῦ θνητοῦ, καὶ τοῦ ⟨λογικοῦ καὶ τοῦ⟩ ἀλόγου.", "st": "XI.10"}, {"sp": "N", "t": "πάντα γὰρ σώματα ζῶντα ἔμψυχα, τὰ δὲ μὴ ζῶντα ὕλη [πάλιν] καθ’ ἑαυτήν ἐστι·", "st": "XI.10b"}, {"sp": "N", "t": "καὶ ψυχὴ ὁμοίως καθ’ ἑαυτήν, τῷ ποιητῇ παρακειμένη, τῆς ζωῆς οὐσία. τῆς δὲ ζωῆς πᾶς αἴτιος ὁ τῶν ἀθανάτων.", "st": "XI.10c"}, {"sp": "N", "t": "πῶς οὖν καὶ τὰ θνητὰ ζῷα ⟨ἡ τῶν ἀθανάτων ζωὴ⟩ ἄλλη ⟨τῆς⟩ τῶν θνητῶν; πῶς δὲ ⟨εὔλογον τὸν⟩ τὰ ἀθάνατα [καὶ ἀθανασίαν] ποιοῦντα ζῷα μὴ ποιεῖν; τῆς δὴ ζωῆς πάσ⟨ης⟩ αἴτιος ὁ ⟨τῆς⟩ τῶν ἀθανάτων.", "st": "XI.10d"}, {"sp": "N", "t": "καὶ ὅτι μὲν ἔστι τις ὁ ποιῶν ταῦτα, δῆλον. ὅτι δὲ καὶ εἷς, φανερώτατον· καὶ γὰρ μία ψυχή, καὶ μία ζωή, καὶ μία ὕλη.", "st": "XI.11"}, {"sp": "N", "t": "τίς δὲ οὗτος; τίς δὲ ἂν ἄλλος ⟨εἴη⟩, εἰ μὴ εἷς ὁ θεός;", "st": "XI.11b"}, {"sp": "N", "t": "τίνι γὰρ ἂν ἄλλῳ πρέποι [ζῷα] ἔμψυχα ποιεῖν, εἰ μὴ μόνῳ τῷ θεῷ;", "st": "XI.11c"}, {"sp": "N", "t": "[εἷς οὖν θεός. γελοιότατον.] καὶ τὸν μὲν κόσμον ὡμολόγησας ἕνα εἶναι, καὶ τὸν ἥλιον ἕνα, καὶ τὴν σελήνην μίαν, καὶ [θειότητα] ⟨τὴν γῆν⟩ μίαν· αὐτὸν δὲ τὸν θεὸν πόστον εἶναι θέλεις;", "st": "XI.11d"}, {"sp": "N", "t": "[πάντα οὖν αὐτὸς ποιεῖ.] εἰ πολλοί, γελοιότατον. καὶ τί μέγα τῷ θεῷ [ζωὴν καὶ ψυχὴν] καὶ ἀθανασίαν καὶ μεταβολὴν ποιεῖν, σοῦ τοσαῦτα ποιοῦντος;", "st": "XI.12"}, {"sp": "N", "t": "καὶ γὰρ βλέπεις, καὶ λαλεῖς, καὶ ἀκούεις, καὶ ὀσφραίνῃ, καὶ ἅπτῃ, καὶ περιπατεῖς, καὶ νοεῖς, καὶ πνεῖς. καὶ οὐχ ἕτερος μέν ἐστιν ὁ βλέπων, ἕτερος δὲ ὁ ἀκούων, ἕτερος δὲ ὁ λαλῶν, ἄλλος δὲ ὁ ἁπτόμενος, ἄλλος δὲ ὁ ὀσφραινόμενος, ἄλλος δὲ ὁ περιπατῶν, καὶ ἄλλος ὁ νοῶν, καὶ ἄλλος ὁ ἀναπνέων· ἀλλὰ εἷς ὁ ταῦτα πάντα ⟨ποιῶν⟩.", "st": "XI.12b"}, {"sp": "N", "t": "ἀλλὰ οὐδὲ δυνατὸν ἐκεῖνα χωρὶς τοῦ ⟨ποιεῖν τὸν⟩ θεὸν εἶναι. ὥσπερ γάρ, ἂν τούτων καταργηθῇς, οὐκέτι ζῷον εἶ, οὕτως, [οὐδ’] ἂν ἐκείνων καταργηθῇ, ὁ θεός, ὃ μὴ θέμις ἐστὶν εἰπεῖν, οὐκέτι ἐστὶ θεός.", "st": "XI.12c"}, {"sp": "N", "t": "εἰ γὰρ ἀποδέδεικται μηδὲν ⟨ποιῶν ἄνθρωπος οὐ⟩ δυνάμενος εἶναι, πόσῳ μᾶλλον ὁ θεός; εἰ γάρ τι ἐστὶν ὃ μὴ ποιεῖ, καὶ ⟨ὁ θεός⟩, ὃ μὴ θέμις εἰπεῖν, ἀτελής ἐστιν· εἰ δὲ μή τι ἀργός ἐστι, τέλειος. ⟨ὁ θεὸς⟩ [δὲ] ἄρα πάντα ποιεῖ.", "st": "XI.13"}, {"sp": "N", "t": "πρὸς ὀλίγον δ’ ἄν μοι σεαυτὸν ἐπιδῷς, ὦ Ἑρμῆ, ῥᾴδιον νοῆσαι τὸ τοῦ θεοῦ ἔργον ἓν ὄν, ἵνα πάντα γίνηται [τὰ γινόμενα, ἢ τὰ ἅπαξ γεγονότα, ἢ τὰ μέλλοντα γίνεσθαι]· ἔστι δὲ τοῦτο, ὦ φίλτατε, ζωή· [τοῦτο δέ ἐστι τὸ καλόν,] τοῦτο δέ ἐστι τὸ ἀγαθόν. [τοῦτο ἔστιν ὁ θεός.]", "st": "XI.13b"}, {"sp": "N", "t": "εἰ δὲ καὶ ἔργῳ αὐτὸ θέλεις νοῆσαι, ἴδε τί σοὶ ἐγγίνεται θέλοντι γεννῆσαι. ἀλλ’ οὐκ ἐκείνῳ τοῦτο ὅμοιον· ἐκεῖνος ⟨γ⟩ὰρ [α] οὐχ ἥδεται·", "st": "XI.14"}, {"sp": "N", "t": "οὐδὲ γὰρ ἄλλο ἔχει συνεργόν. αὐτουργὸς [γ] ἄρ⟨α⟩ ὤν, ἀεί ἐστιν ἐν τῷ ἔργῳ, αὐτὸς ὢν ὃ ποιεῖ. εἰ γὰρ χωρισθείη αὐτοῦ, πάντα μὲν συμπεσεῖσθαι, πάντα δὲ τεθνήξεσθαι ἀνάγκη, ὡς μὴ οὔσης ζωῆς.", "st": "XI.14b"}, {"sp": "N", "t": "εἰ δὲ πάντα ζῷα, [μία δὲ καὶ ἡ ζωή,] ⟨…⟩. εἷς ἄρα καὶ ὁ θεός. καὶ πάλιν, εἰ πάντα ζῷά ἐστι, καὶ τὰ ἐν οὐρανῷ καὶ τὰ ἐν τῇ γῇ, μία δὲ κατὰ πάντων ζωὴ ὑπὸ τοῦ θεοῦ γίνεται, καὶ αὕτη ἐστὶ θεός, ὑπὸ τοῦ θεοῦ ἄρα γίνεται πάντα.", "st": "XI.14c"}, {"sp": "N", "t": "[ζωὴ δέ ἐστιν ἕνωσις [νοῦ] ⟨σώματος⟩ καὶ ψυχῆς. θάνατος δὴ οὐκ ἀπώλεια τῶν συναχθέντων, διάλυσις δὲ τῆς ἑνώσεώς ἐστι.]", "st": "XI.14d"}, {"sp": "N", "t": "[τοίνυν εἰκὼν τοῦ θεοῦ ὁ αἰών, τοῦ δὲ αἰῶνος ὁ κόσμος, τοῦ δὲ κόσμου ὁ ἥλιος, τοῦ δὲ ἡλίου ὁ ἄνθρωπος.]", "st": "XI.15"}, {"sp": "N", "t": "⟨…⟩ τὴν δὲ μεταβολὴν θάνατόν φασιν εἶναι, διὰ τὸ τὸ μὲν σῶμα διαλύεσθαι, τὴν δὲ ζωὴν εἰς τὸ ἀφανὲς χωρεῖν [τὰ διαλυόμενα]. τούτῳ τῷ λόγῳ, φίλτατέ μοι Ἑρμῆ, καὶ τὸν κόσμον [δεισιδαίμων ὡς] ⟨δι’ αἰῶνός⟩ [ἀκούεις] φημι μεταβάλλεσθαι, διὰ τὸ γίνεσθαι μέρος ⟨τι τῆς ζωῆς⟩ αὐτοῦ καθ’ ἑκάστην ἡμέραν ἐν τῷ ἀφανεῖ, μηδέποτε ⟨δὲ⟩ διαλύεσθαι.", "st": "XI.15b"}, {"sp": "N", "t": "καὶ ταῦτά ἐστι τὰ τοῦ κόσμου πάθη, †δινήσεις τε καὶ κρύψεις· καὶ ἡ μὲν δίνησις στροφή, ἡ δὲ κρύψις ἀνανέωσις†·", "st": "XI.15c"}, {"sp": "N", "t": "⟨…⟩ παντόμορφος δέ ἐστιν, οὐ τὰς μορφὰς ἐγκειμένας ἔχων ἐν ἑαυτῷ, δὲ αὐτὸς μεταβάλλων.", "st": "XI.16"}, {"sp": "N", "t": "ἐπεὶ οὖν ὁ κόσμος παντόμορφος γέγονεν, ὁ ποιήσας τί ἂν εἴη; ἄμορφος μὲν γὰρ μὴ γένοιτο· εἰ δὲ καὶ αὐτὸς παντόμορφος, ὅμοιος ἔσται τῷ κόσμῳ. ἀλλὰ μίαν ἔχων μορφήν, κατὰ τοῦτο ἐλάττων ἔσται τοῦ κόσμου.", "st": "XI.16b"}, {"sp": "N", "t": "τί οὖν φῶμεν αὐτὸν εἶναι; μὴ εἰς ἀπορίαν τὸν λόγον περιστήσωμεν· οὐδὲν γὰρ ἄπορον περὶ τοῦ θεοῦ νοουμένοις.", "st": "XI.16c"}, {"sp": "N", "t": "μίαν οὖν ἔχει ἰδέαν, [εἴ τις ἔστιν αὐτοῦ ἰδέα,] ἥτις ταῖς ὄψεσιν οὐχ ὑποσταίη· ἀσώματος ⟨γάρ⟩. [καὶ πάσας διὰ τῶν σωμάτων δείκνυσι.] καὶ μὴ θαυμάσῃς εἰ ἔστι τις ἀσώματος ἰδέα· ἔστι γάρ·", "st": "XI.17"}, {"sp": "N", "t": "ὥσπερ [ἡ τοῦ λόγου] καὶ ἐν ταῖς γραφαῖς ἀκρώρειαι ὁρῶνται μὲν [γὰρ] πάνυ ἐξέχουσαι, λεῖαι δὲ τῇ φύσει καὶ ὁμαλαί εἰσι παντελῶς.", "st": "XI.17b"}, {"sp": "N", "t": "ἐννοήσας δὲ τὸ λεγόμενον τολμηρότερον, ἀληθέστερον [δὲ] νοήσεις τὸν περιέχοντα τὰ πάντα.", "st": "XI.17c"}, {"sp": "N", "t": "ὥσπερ γὰρ ὁ ἄνθρωπος χωρὶς ζωῆς οὐ δύναται ζῆν, οὕτως οὐδὲ ὁ θεὸς δύναται μὴ ποιῶν τὸ ἀγαθόν. τοῦτο γὰρ ὥσπερ ζωὴ καὶ ὥσπερ κίνησίς ἐστι τοῦ θεοῦ, κινεῖν τὰ πάντα καὶ ζωοποιεῖν.", "st": "XI.17d"}, {"sp": "N", "t": "ἔνια δὲ τῶν λεγομένων ἰδίαν ἔννοιαν ἔχειν ὀφείλει, οἷον ὃ λέγω ⟨νῦν⟩ [νόησον].", "st": "XI.18"}, {"sp": "N", "t": "πάντα ⟨γάρ⟩ ἐστιν ἐν τῷ θεῷ, οὐχ ὡς ἐν τόπῳ κείμενα· ὁ μὲν γὰρ τόπος [καὶ] σῶμά ἐστι, καὶ ⟨πᾶν⟩ σῶμα ⟨κινητόν· τὸ δὲ ἀσώματον⟩ ἀκίνητον, καὶ τὰ ⟨ἐν αὐτῷ⟩ κείμενα κίνησιν οὐκ ἔχει·", "st": "XI.18b"}, {"sp": "N", "t": "κεῖται γὰρ ἄλλως ἐν ἀσωμάτῳ [φαντασίᾳ].", "st": "XI.18c"}, {"sp": "N", "t": "νόησον τὸν περιέχοντα τὰ πάντα. καὶ [νόησον ὅτι] τοῦ ἀσωμάτου οὐδέν ἐστι περιοριστικόν, [οὐδὲ ταχύτερον, οὐδὲ δυνατώτερον,] αὐτὸ δὲ πάντων ⟨περιοριστικόν⟩, [καὶ ἀπεριόριστον καὶ] ταχύτατον ⟨ὂν⟩ καὶ δυνατώτατον.", "st": "XI.18d"}, {"sp": "N", "t": "καὶ ⟨τ⟩οῦτο νόησον ἀπὸ σεαυτοῦ. [καὶ] κέλευσόν σου τῇ ψυχῇ εἰς ἣν δὴ καὶ ⟨βούλει γῆν⟩ πορευθῆναι, καὶ ταχύτερόν σου τῆς κελεύσεως ἐκεῖ ἔσται. μετελθεῖν δὲ αὐτῇ κέλευσον ἐπὶ τὸν ὠκεανόν, καὶ οὕτως ἐκεῖ πάλιν ταχέως ἔσται, οὐχ ὡς μεταβᾶσα ἀπὸ τόπου εἰς τόπον, ἀλλ’ ὡς ἐκεῖ οὖσα.", "st": "XI.19"}, {"sp": "N", "t": "κέλευσον δὲ αὐτῇ καὶ εἰς τὸν οὐρανὸν ἀναπτῆναι, καὶ οὐδὲ πτερῶν δεηθήσεται· ἀλλ’ οὐδὲ αὐτῇ οὐδὲν ἐμπόδιον, οὐ τὸ τοῦ ἡλίου πῦρ, [οὐχ ὁ αἰθήρ,] οὐχ ἡ ⟨τῶν ἀστέρων⟩ δίνη [οὐχὶ τὰ τῶν ἄλλων ἀστέρων σώματα]· πάντα δὲ διατεμοῦσα ἀναπτήσεται μέχρι τοῦ ἐσχάτου σώματος. εἰ δὲ βουληθείης καὶ αὐτὸ ⟨τὸ⟩ ὅλον διαρρήξασθαι, καὶ τὰ ἐκτός, εἴ γέ τι ἐκτὸς τοῦ κόσμου, θεάσασθαι, ἔξεστί σοι.", "st": "XI.19b"}, {"sp": "N", "t": "ἴδε ὅσην δύναμιν, ὅσον τάχος ἔχεις. εἶτα σὺ μὲν δύνασαι ταῦτα, ὁ θεὸς δὲ οὔ;", "st": "XI.20"}, {"sp": "N", "t": "τοῦτον οὖν τὸν τρόπον νόησον τὸν θεόν, ὥσπερ νοήματα, πάντα ἐν ἑαυτῷ ἔχειν, τὸν κόσμον, ἑαυτόν, ⟨τὸ⟩ ὅλον.", "st": "XI.20b"}, {"sp": "N", "t": "ἐὰν οὖν μὴ σεαυτὸν ἐξισάσῃς τῷ θεῷ, τὸν θεὸν νοῆσαι οὐ δύνασαι· τὸ γὰρ ὅμοιον τῷ[ν] ὁμοίῳ[ν] νοητόν.", "st": "XI.20c"}, {"sp": "N", "t": "συναύξησον σεαυτὸν τῷ ἀμετρήτῳ μεγέθει παντὸς σώματος ἐκπηδήσας, καὶ πάντα χρόνον ὑπεράρας αἰών⟨ιος⟩ γενοῦ, καὶ νοήσεις τὸν θεόν.", "st": "XI.20d"}, {"sp": "N", "t": "μηδὲν ἀδύνατον σεαυτῷ ὑπόστησαι· σεαυτὸν ἥγησαι ἀθάνατον, καὶ πάντα δυνάμενον νοῆσαι, πᾶσαν μὲν τέχνην, πᾶσαν δὲ ἐπιστήμην.", "st": "XI.20e"}, {"sp": "N", "t": "παντὸς ζῴου ἤθη ⟨…⟩, παντὸς δὲ ὕψους ὑψηλότερος γενοῦ, καὶ παντὸς βάθους ταπεινότερος· πάσας δὲ τὰς ἀντιθέσεις τῶν ποι⟨οτ⟩ήτων σύλλαβε ἐν σεαυτῷ, [πυρός, ὕδατος,] ⟨θερμοῦ καὶ ψυχροῦ,⟩ ξηροῦ καὶ ὑγροῦ· καὶ ὁμοῦ πανταχῆ ⟨νόησον⟩ εἶναι, ἐν γῇ, ἐν θαλάττῃ, ἐν οὐρανῷ· μηδέπω γεγεν⟨ν⟩ῆσθαι, ἐν τῇ γαστρὶ εἶναι, νέος, γέρων, τεθνηκέναι, τὰ μετὰ τὸν θάνατον·", "st": "XI.20f"}, {"sp": "N", "t": "καὶ ταῦτα πάντα ὁμοῦ νοήσας, χρόνους, τόπους, πράγματα, ποιότητας, ποσότητας, δύνασαι νοῆσαι τὸν θεόν.", "st": "XI.20g"}, {"sp": "N", "t": "ἐὰν δὲ κατακλείσῃς σου τὴν ψυχὴν ἐν τῷ σώματι, καὶ ταπεινώσῃς ἑαυτόν, καὶ εἴπῃς Οὐδὲν νοῶ, οὐδὲν δύναμαι· φοβοῦμαι γῆν ⟨καὶ⟩ θάλασσαν· εἰς τὸν οὐρανὸν ἀναβῆναι οὐ δύναμαι· οὐκ οἶδα τίς ἤμην, οὐκ οἶδα τίς ἔσομαι·", "st": "XI.21"}, {"sp": "N", "t": "τί σοι καὶ τῷ θεῷ; οὐδὲν γὰρ δύνασαι τῶν καλῶν καὶ ἀγαθῶν, φιλοσώματος ὢν καὶ κακὸς νοῆσαι.", "st": "XI.21b"}, {"sp": "N", "t": "ἡ γὰρ τελεία κακία τὸ ἀγνοεῖν τὸ⟨ν⟩ θε[ι]όν· τὸ δὲ δύνασθαι γνῶναι, καὶ θελῆσαι, καὶ ἐλπίσαι, ὁδός ἐστιν εὐθὺ [ἰδία] τοῦ ἀγαθοῦ φέρουσα, καὶ ῥᾳδία ὁδεύοντι σοι.", "st": "XI.21c"}, {"sp": "N", "t": "πανταχοῦ συναντήσει ⟨ὁ θεός⟩, καὶ πανταχοῦ ὀφθήσεται, ὅπου καὶ ὅτε οὐ προσδοκᾷς, γρηγοροῦντι κοιμωμένῳ, πλέοντι ὁδεύοντι, νυκτὸς ἡμέρας, λαλοῦντι σιωπῶντι· οὐδὲν γάρ ἐστιν ὃ οὐκ ἔστιν [εἰκόνι] ⟨ἐκεῖνος⟩.", "st": "XI.21d"}, {"sp": "N", "t": "εἶτα φῂς ἀόρατος ὁ θεός; εὐφήμησον.", "st": "XI.22"}, {"sp": "N", "t": "καὶ τίς αὐτοῦ φανερώτερος; δι’ αὐτὸ τοῦτο πάντα πεποίηκεν, ἵνα διὰ πάντων αὐτὸν βλέπῃς.", "st": "XI.22b"}, {"sp": "N", "t": "[τοῦτο ἔστι τὸ ἀγαθὸν] τοῦ θεοῦ, τοῦτο ἡ ἀρετή, τὸ αὐτὸν φαίνεσθαι διὰ πάντων.", "st": "XI.22c"}, {"sp": "N", "t": "οὐδὲν γὰρ ⟨ἀ⟩όρατον, οὐδὲ τῶν ἀσωμάτων· ⟨ὁ⟩ νοῦς ὁρᾶται ἐν τῷ νοεῖν, ὁ θεὸς ἐν τῷ ποιεῖν.", "st": "XI.22d"}, {"sp": "N", "t": "ταῦτά σοι ἐπὶ τοσοῦτον πεφανέρωται, ὦ τρισμέγιστε. τὰ δὲ ἄλλα πάντα ὁμοίως κατὰ σεαυτὸν νόει, καὶ οὐ διαψευσθήσῃ", "st": "XI.22e"}, {"sp": "HDR", "t": "Περὶ νοῦ κοινοῦ πρὸς Τάτ"}, {"sp": "N", "t": "Ὁ νοῦς, ὦ Τάτ, ἐξ αὐτῆς τῆς τοῦ θεοῦ οὐσίας ἐστίν, εἴ γέ τις ἔστιν οὐσία θεοῦ· καὶ ποία τις οὖσα τυγχάνει, αὐτὸς μόνος ἀκριβῶς [αὐτὸν] οἶδεν.", "st": "XII.1"}, {"sp": "N", "t": "ὁ νοῦς οὖν οὐκ ἔστιν ἀποτετμημένος τῆς οὐσιότητος τοῦ θεοῦ, ἀλλ’ ὥσπερ ἡπλωμένος, καθάπερ τὸ τοῦ ἡλίου φῶς.", "st": "XII.1b"}, {"sp": "N", "t": "οὗτος δὲ ὁ νοῦς ἐν μὲν ἀνθρώποις †θεός† ἐστι· διὸ καί τινες τῶν ἀνθρώπων θε⟨ῖ⟩οί εἰσι, καὶ ἡ ⟨τ⟩ούτων ἀνθρωπότης ἐγγύς ἐστι τῆς θεότητος·", "st": "XII.1c"}, {"sp": "N", "t": "καὶ γὰρ ὁ Ἀγαθὸς Δαίμων τοὺς μὲν θεοὺς ⟨ἀνθρώπους⟩ εἶπεν ἀθανάτους, τοὺς δὲ ἀνθρώπους θεοὺς θνητούς.", "st": "XII.1d"}, {"sp": "N", "t": "ἐν δὲ τοῖς ἀλόγοις ζῴοις ⟨…⟩ ἡ φύσις ἐστίν. ὅπου γὰρ [ψυχή, ἐκεῖ καὶ νοῦς ἐστιν, ὥσπερ ὅπου καὶ] ζωή, ἐκεῖ καὶ ψυχή ἐστιν·", "st": "XII.2"}, {"sp": "N", "t": "ἐν δὲ τοῖς ἀλόγοις ζῴοις ἡ ψυχή [ζωή] ἐστι κενὴ τοῦ νοῦ. ὁ γὰρ νοῦς ψυχῶν ἐστιν εὐεργέτης ἀνθρώπων· ἐργάζεται γὰρ αὐτα⟨ῖ⟩ς [εἰς] τὸ ἀγαθόν.", "st": "XII.2b"}, {"sp": "N", "t": "καὶ τοῖς μὲν ἀλόγοις τῇ ⟨ἰ⟩δί⟨ᾳ⟩ ἑκάστου φύσει συνεργεῖ, ταῖς δὲ τῶν ἀνθρώπων ἀντιπράσσει.", "st": "XII.2c"}, {"sp": "N", "t": "ψυχὴ γὰρ πᾶσα, ἐν σώματι γενομένη, εὐθέως ὑπό τε τῆς λύπης καὶ τῆς ἡδονῆς κακίζεται·", "st": "XII.2d"}, {"sp": "N", "t": "σώματος γὰρ συνθέτου ὥσπερ χυμοὶ ζέουσιν ἥ τε λύπη καὶ ἡ ἡδονή, εἰς ἃς ἐμβᾶσα ἡ ψυχὴ βαπτίζεται.", "st": "XII.2e"}, {"sp": "N", "t": "ὅσαις ἂν οὖν ψυχαῖς ὁ νοῦς ἐπιστατήσῃ, ταύταις φαίνει ἑαυτοῦ τὸ φέγγος, ἀντιπράσσων αὐτῶν τοῖς προλήμμασιν.", "st": "XII.3"}, {"sp": "N", "t": "ὥσπερ ⟨γὰρ⟩ ἰατρὸς ἀγαθὸς λυπεῖ τὸ σῶμα προειλημμένον ὑπὸ νόσου καίων ἢ τέμνων, τὸν αὐτὸν τρόπον καὶ ὁ νοῦς ⟨τὴν⟩ ψυχὴν λυπεῖ, ἐξυφαιρῶν αὐτῆς τὴν ἡδονήν, ἀφ’ ἧς πᾶσα νόσος ψυχῆς γίνεται.", "st": "XII.3b"}, {"sp": "N", "t": "νόσος δὲ μεγάλη ψυχῆς ἀθεότης· ἐπεὶ τα⟨ῖς τῶν ἀθέων⟩ δόξα[ε]ις πάντα τὰ κακὰ ἐπακολουθεῖ, καὶ ἀγαθὸν οὐδέν.", "st": "XII.3c"}, {"sp": "N", "t": "ἆρ’ οὖν ὁ νοῦς, ἀντιπράσσων αὐτῇ, τὸ ἀγαθὸν περιποιεῖται τῇ ψυχῇ, ὥσπερ καὶ ὁ ἰατρὸς τῷ σώματι τὴν ὑγίειαν.", "st": "XII.3d"}, {"sp": "N", "t": "ὅσαι δὲ ψυχαὶ ἀνθρώπιναι οὐκ ἔτυχον κυβερνήτου τοῦ νοῦ, τὸ αὐτὸ πάσχουσι ταῖς τῶν ἀλόγων ζῴων.", "st": "XII.4"}, {"sp": "N", "t": "συνεργὸς γὰρ αὐταῖς γενόμενος, καὶ ἀνέσας τὰς ἐπιθυμίας, ⟨…⟩ εἰς ἃς φέρονται τῇ ῥύμῃ τῆς ὀρέξεως, πρὸς τὸ ἄλογον συντείνουσαι. καὶ ὥσπερ τὰ ἄλογα τῶν ζῴων, ἀλόγως θυμούμεναι καὶ ἀλόγως ἐπιθυμοῦσαι οὐ παύονται, οὐδὲ κόρον ἔχουσι τῶν κακῶν·", "st": "XII.4b"}, {"sp": "N", "t": "θυμοὶ γὰρ καὶ ἐπιθυμίαι ἄλογοι κακίαι ὑπερβάλλουσαι. ταύταις δὲ ὥσπερ τιμωρὸν καὶ ἔλεγχον ὁ θεὸς ἐπέστησε τὸν νόμον.", "st": "XII.4c"}, {"sp": "N", "t": "— Ἐνταῦθα, ὦ πάτερ, ὁ περὶ τῆς εἱμαρμένης λόγος, ὃ⟨ν⟩ ἔμπροσθέν μοι ⟨δι⟩εξελήλυθας, κινδυνεύει ἀνατρέπεσθαι.", "st": "XII.5"}, {"sp": "N", "t": "εἰ γὰρ πάντως εἵμαρται τῷδέ τινι μοιχεῦσαι, ἢ ἱεροσυλῆσαι, ἢ ἄλλο τι κακὸν δρᾶσαι, διὰ τί κολάζεται ὁ [ἐξ] ἀναγκ⟨ασάσ⟩ης τῆς εἱμαρμένης δράσας τὸ ἔργον;", "st": "XII.5b"}, {"sp": "N", "t": "εἱμαρμένης γὰρ πάντα τὰ ἔργα.<br>— ⟨...,⟩ ὦ τέκνον, καὶ χωρὶς ἐκείνης οὐδὲν [τι] τῶν σωματικῶν, οὔτε ἀγαθὸν οὔτε κακόν, γενέσθαι συμβαίνει·", "st": "XII.5c"}, {"sp": "N", "t": "εἵμαρται δὲ καὶ ⟨τὸν⟩ τὸ κακὸν ποιήσαντα [τὸ] ⟨κακὸν⟩ παθεῖν· καὶ διὰ τοῦτο δρᾷ, ἵνα πάθῃ ὃ πάσχει ὅτι ἔδρασε.", "st": "XII.5d"}, {"sp": "N", "t": "τὸ δὲ νῦν ἔχον, ο⟨ὐ⟩ περὶ κακίας καὶ εἱμαρμένης ⟨ὁ⟩ λόγος· ἐν ἄλλοις μὲν ⟨γὰρ⟩ περὶ τούτων εἰρήκαμεν, νῦν δὲ περὶ νοῦ ἐστιν ἡμῖν ὁ λόγος, τί δύναται νοῦς, καὶ πῶς ἐνδιάφορός ἐστιν, ἐν μὲν ἀνθρώποις τοιόσδε, ἐν δὲ τοῖς ἀλόγοις ζῴοις ἠλλαγμένος· καὶ πάλιν, ὅτι ἐν μὲν τοῖς ἀλόγοις ζῴοις οὐκ ἔστιν εὐεργετικός, ⟨ἐν δὲ τοῖς ἀνθρώποις ἀγαθὸν ἐργάζεται,⟩ ἀλλ’ ἀνομοίως, ⟨οὐκ⟩ ἐν πᾶσι τό τε θυμικὸν καὶ τὸ ἐπιθυμητικὸν σβεννύων.", "st": "XII.6"}, {"sp": "N", "t": "καὶ τούτων τοὺς μὲν ἐλλογίμους [ἄνδρας] δεῖ νοεῖν, τοὺς δὲ ἀλόγους.", "st": "XII.6b"}, {"sp": "N", "t": "πάντες δὲ οἱ ἄνθρωποι εἱμαρμένῃ ὑπόκεινται, ⟨ἐπεὶ⟩ καὶ γενέσει καὶ μεταβολῇ· ἀρχὴ γὰρ καὶ τέλος ταῦτα εἱμαρμένης.", "st": "XII.6c"}, {"sp": "N", "t": "καὶ πάντες μὲν ἄνθρωποι πάσχουσι τὰ εἱμαρμένα· οἱ δὲ ἐλλόγιμοι, ὧν ἔφαμεν τὸν νοῦν ἡγεμονεύειν, οὐχ ὁμοίως τοῖς ἄλλοις πάσχουσιν, ἀλλὰ τῆς κακίας ἀπηλλαγμένοι· οὐ ⟨γὰρ⟩ κακοὶ ὄντες πάσχουσι.", "st": "XII.7"}, {"sp": "N", "t": "— Πῶς πάλιν λέγεις, ὦ πάτερ; ὁ μοιχὸς οὐ κακός; ὁ φονεὺς οὐ κακός, καὶ οἱ ἄλλοι πάντες;", "st": "XII.7b"}, {"sp": "N", "t": "— Ἀλλ’ ὁ ἐλλόγιμος, ὦ τέκνον, οὐ μοιχεύσας πείσεται, ἀλλ’ ὡς ⟨ὁ⟩ μοιχεύσας, οὐδὲ φονεύσας, ἀλλ’ ὡς ⟨ὁ⟩ φονεύσας.", "st": "XII.7c"}, {"sp": "N", "t": "καὶ †ποιότητα† μεταβολῆς ἀδύνατόν ἐστι διεκφυγεῖν, ὥσπερ καὶ γενέσεως·", "st": "XII.7d"}, {"sp": "N", "t": "κακίαν δὲ τῷ νοῦν ἔχοντι διεκφυγεῖν ἔστι.", "st": "XII.7e"}, {"sp": "N", "t": "[διὸ] καὶ τοῦ Ἀγαθοῦ Δαίμονος, ὦ τέκνον, ἐγὼ ἤκουσα λέγοντος ἃ εἰ καὶ [εἰ] ἐγγράφως ⟨ἐξ⟩εδεδώκει, πάνυ ἂν τὸ τῶν ἀνθρώπων γένος ὠφελήκει· ἐκεῖνος γὰρ μόνος, ὦ τέκνον, ἀληθῶς ὡς πρωτόγονος θεός, τὰ πάντα κατιδών, θείους λόγους ἐφθέγξατο.", "st": "XII.8"}, {"sp": "N", "t": "ἤκουσα γοῦν αὐτοῦ ποτε λέγοντος ὅτι †ἕν ἐστι τὰ πάντα, καὶ μάλιστα νοητὰ σώματα· ζῶμεν δὲ δυνάμει καὶ ἐνεργείᾳ καὶ αἰῶνι. καὶ ὁ νοῦς τούτου ἀγαθός ἐστιν, ὅπερ ἐστὶν αὐτοῦ καὶ ψυχή· τούτου δὲ τοιούτου ὄντος, οὐδὲν διαστατὸν τῶν νοητῶν· ὡς οὖν δυνατὸν νοῦν, ἄρχοντα πάντων, καὶ ψυχὴν ὄντα τοῦ θεοῦ, ποιεῖν ὅπερ βούλεται†.", "st": "XII.8b"}, {"sp": "N", "t": "σὺ δὲ νόει, καὶ τὸν λόγον τοῦτον ἀνένεγκαι πρὸς τὴν πεῦσιν ἣν ἐπύθου μου ἐν τοῖς ἔμπροσθεν, λέγω δὲ περὶ τῆς εἱμαρμένης [τοῦ νοῦ].", "st": "XII.9"}, {"sp": "N", "t": "ἐὰν γὰρ τοὺς ἐριστικοὺς λόγους ἀκριβῶς ἀφέλῃ, ὦ τέκνον, εὑρήσεις ὅτι ἀληθῶς πάντων ἐπικρατεῖ ὁ νοῦς [ἡ τοῦ θεοῦ ψυχή], καὶ εἱμαρμένης, καὶ νόμου, καὶ τῶν ἄλλων πάντων· καὶ οὐδὲν αὐτῷ ἀδύνατον, οὔτε εἱμαρμένης ὑπεράνω θε⟨ῖναι⟩ [νοῦν] ψυχὴν ἀνθρωπίνην, οὔτε ἀμελήσασαν, ἅπερ συμβαίνει, ὑπὸ τὴν εἱμαρμένην ⟨θ⟩εῖναι. καὶ ταῦτα μὲν ἐπὶ τοσοῦτον λελέχθω. [τὰ τοῦ Ἀγαθοῦ Δαίμονος ἄριστα.]", "st": "XII.9b"}, {"sp": "N", "t": "— Καὶ θείως, ὦ πάτερ, ταῦτα, καὶ ἀληθῶς καὶ ὠφελίμως.", "st": "XII.9c"}, {"sp": "N", "t": "ἐκεῖνο δέ μοι ἔτι διασάφησον· ἔλεγες γὰρ τὸν νοῦν ἐν τοῖς ἀλόγοις ζῴοις φύσεως δίκην ἐνεργεῖν, συνεργοῦντα αὐτῶν ταῖς ὁρμαῖς.", "st": "XII.10"}, {"sp": "N", "t": "αἱ δὲ ὁρμαὶ τῶν ἀλόγων ζῴων, ὡς οἶμαι, πάθη εἰσίν·", "st": "XII.10b"}, {"sp": "N", "t": "εἰ δὲ καὶ ὁ νοῦς συνεργεῖ ταῖς ὁρμαῖς, αἱ δὲ ὁρμαὶ πάθη, καὶ ὁ νοῦς ἄρα παθ⟨ητ⟩ός ἐστι, συγχρω[μα]τίζων τοῖς πάθεσιν.", "st": "XII.10c"}, {"sp": "N", "t": "— Εὖγε, ὦ τέκνον· γενναίως πυνθάνῃ, δίκαιον δὲ κἀμὲ ἀποκρίνασθαι.", "st": "XII.10d"}, {"sp": "N", "t": "πάντα, ὦ τέκνον, τὰ ἐν σώματι ἀσώματα παθητά. καὶ κυρίως ⟨μὲν⟩ αὐτά ἐστι παθη⟨τά⟩· ⟨…⟩.", "st": "XII.11"}, {"sp": "N", "t": "πᾶν γὰρ τὸ κινοῦν ἀσώματον, πᾶν δὲ τὸ κινούμενον σῶμα·", "st": "XII.11b"}, {"sp": "N", "t": "καὶ τὰ ἀσώματα δὲ [κινεῖται ὑπὸ τοῦ νοῦ·] [κίνησις δὲ πάθος·] πάσχει οὖν ἀμφότερα, καὶ τὸ κινοῦν καὶ τὸ κινούμενον, τὸ μὲν ἄρχον, τὸ δὲ ἀρχόμενον.", "st": "XII.11c"}, {"sp": "N", "t": "⟨ὥστε καὶ ὁ νοῦς, ἐν σώματι μὲν ὤν, παθητός ἐστιν,⟩ ἀπαλλαγεὶς δὲ τοῦ σώματος, ἀπηλλάγη καὶ τοῦ πάθους.", "st": "XII.11d"}, {"sp": "N", "t": "†μᾶλλον δέ ποτε, ὦ τέκνον, οὐδὲν ἀπαθές, πάντα δὲ παθητά.", "st": "XII.11e"}, {"sp": "N", "t": "διαφέρει δὲ πάθος παθητοῦ. τὸ μὲν γὰρ ἐνεργεῖ, τὸ δὲ πάσχει·", "st": "XII.11f"}, {"sp": "N", "t": "τὰ δὲ σώματα καὶ καθ’ αὑτὰ ἐνεργεῖ. ἢ γὰρ ἀκίνητά ἐστιν ἢ κινεῖται·", "st": "XII.11g"}, {"sp": "N", "t": "ὁπότερον δὲ ἂν ᾖ, πάθος ἐστί. τὰ δὲ ἀσώματα ἀεὶ ἐνεργεῖται, καὶ διὰ τοῦτο παθητά ἐστι.† μὴ οὖν σε αἱ προσηγορίαι ταραττέτωσαν·", "st": "XII.11h"}, {"sp": "N", "t": "†ἥ τε γὰρ ἐνέργεια καὶ τὸ πάθος ταὐτόν ἐστιν·† εὐφημοτέρῳ δὲ τῷ ὀνόματι χρήσασθαι οὐ λυπεῖ.", "st": "XII.11i"}, {"sp": "N", "t": "— Σαφέστατα, ὦ πάτερ, τὸν λόγον ἀποδέδωκας.", "st": "XII.11j"}, {"sp": "N", "t": "— Κἀκεῖνο δὲ ὅρα, ὦ τέκνον, ὅτι δύο ταῦτα τῷ ἀνθρώπῳ ὁ θεὸς παρὰ πάντα τὰ θνητὰ ζῷα ἐχαρίσατο, τόν τε νοῦν καὶ τὸν λόγον, ἰσότιμα τῇ ἀθανασίᾳ·", "st": "XII.12"}, {"sp": "N", "t": "[τὸν δὲ προφορικὸν ⟨λ⟩έγει·] τούτοις δὲ εἴ τις χρήσαιτο εἰς ἃ δεῖ, οὐδὲν τῶν ἀθανάτων διοίσει, μᾶλλον δὲ ⟨τῷ ἐν σώματι εἶναι μόνον διοίσει,⟩ καὶ ἐξελθὼν ἐκ τοῦ σώματος, ὁδηγηθήσεται ὑπὸ ἀμφοτέρων εἰς τὸν τῶν θεῶν καὶ μακάρων χορόν.", "st": "XII.12b"}, {"sp": "N", "t": "— Τὰ γὰρ ἄλλα ζῷα λόγῳ οὐ χρῆται, ὦ πάτερ;", "st": "XII.13"}, {"sp": "N", "t": "— Οὔ, τέκνον, ἀλλὰ φωνῇ. πάμπολυ δὲ διαφέρει λόγος φωνῆς· ὁ μὲν γὰρ λόγος κοινὸς πάντων ἀνθρώπων, ἰδία δὲ ἑκάστου φωνή ἐστι γένους ζῴου.", "st": "XII.13b"}, {"sp": "N", "t": "— Ἀλλὰ καὶ τῶν ἀνθρώπων, ὦ πάτερ, ἕκαστον κατὰ ἔθνος διάφορος ὁ λόγος.", "st": "XII.13c"}, {"sp": "N", "t": "— Διάφορος μέν, ὦ τέκνον, ⟨ἡ διάλεκτος,⟩ εἷς δὲ ὁ ἄνθρωπος, οὕτω καὶ ὁ λόγος εἷς ἐστι·", "st": "XII.13d"}, {"sp": "N", "t": "καὶ μεθερμηνεύεται, καὶ ὁ αὐτὸς εὑρίσκεται καὶ ἐν Αἰγύπτῳ καὶ Περσίδι καὶ Ἑλλάδι. ⟨…⟩", "st": "XII.13e"}, {"sp": "N", "t": "ὁ γὰρ μακάριος θεὸς Ἀγαθὸς Δαίμων ψυχὴν μὲν ἐν σώματι ἔφη εἶναι, νοῦν δὲ ἐν ψυχῇ, [λόγον] ⟨θεὸν⟩ δὲ ἐν τῷ νῷ. [τὸν οὖν θεὸν τούτων πατέρα.]", "st": "XII.13f"}, {"sp": "N", "t": "ὁ οὖν λόγος ἐστὶν εἰκὼν καὶ νοῦς τοῦ θεοῦ [καὶ τὸ σῶμα δὲ τῆς ἰδέας, ἡ δὲ ἰδέα τῆς ψυχῆς.] ἔστιν οὖν τῆς μὲν ὕλης τὸ λεπτομερέστατον ἀήρ, ἀέρος δὲ ψυχή, ψυχῆς δὲ νοῦς, νοῦ δὲ θεός.", "st": "XII.14"}, {"sp": "N", "t": "καὶ ὁ μὲν θεὸς περὶ πάντα καὶ διὰ πάντων, ὁ δὲ νοῦς περὶ τὴν ψυχήν, ἡ δὲ ψυχὴ περὶ τὸν ἀέρα, ὁ δὲ ἀὴρ περὶ τὴν ὕλην.", "st": "XII.14b"}, {"sp": "N", "t": "⟨…⟩ ἀνάγκη δὲ καὶ [ἡ] πρόνοια καὶ [ἡ] φύσις ὄργανά ἐστι ⟨τῆς διοικήσεως⟩ τοῦ κόσμου, καὶ τῆς τάξεως τῆς ὕλης. καὶ τῶν μὲν νοητῶν ἕκαστόν ἐστιν ⟨ἕν⟩ [οὐσία], οὐσία δὲ αὐτῶν ἡ ταυτότης·", "st": "XII.14c"}, {"sp": "N", "t": "τῶν δὲ τοῦ παντὸς σωμάτων ἕκαστον πολλά ἐστιν. ἔχετα⟨ι⟩ γὰρ τῆς ταυτότητος τὰ ⟨ἀ⟩σύνθετα σώματα, καὶ τὴν μεταβολὴν εἰς ἄλληλα ποιούμενα, ἀεὶ τῆς ταυτότητος τὴν ἀφθαρσίαν σώζει.", "st": "XII.14d"}, {"sp": "N", "t": "ἐν δὲ τοῖς [ἄλλοις] συνθέτοις πᾶσι σώμασιν ἀριθμὸς ἑκάστου ἐστί· χωρὶς γὰρ ἀριθμοῦ σύστασιν ἢ σύνθεσιν [ἢ διάλυσιν] ἀδύνατον γενέσθαι.", "st": "XII.15"}, {"sp": "N", "t": "αἱ δὲ ἑνάδες τὸν ἀριθμὸν γεννῶσι καὶ αὔξουσι, καὶ πάλιν διαλυόμενον εἰς ἑαυτὰς δέχονται.", "st": "XII.15b"}, {"sp": "N", "t": "καὶ ἡ ὕλη μία. ὁ δὲ σύμπας κόσμος οὗτος, ὁ μέγας θεός, καὶ τοῦ μείζονος εἰκών, καὶ ἡνωμένος ἐκείνῳ, καὶ σώζων τὴν τάξιν κατ⟨ὰ τὴν⟩ βούλησιν τοῦ πατρός, πλήρωμά ἐστι τῆς ζωῆς·", "st": "XII.15c"}, {"sp": "N", "t": "καὶ οὐδέν ἐστιν ἐν τούτῳ, διὰ παντὸς τοῦ αἰῶνος τῆς πρώτης ἀποκαταστάσεως, οὔτε τοῦ παντὸς οὔτε τῶν κατὰ μέρος, ὃ οὐχὶ ζῇ.", "st": "XII.15d"}, {"sp": "N", "t": "νεκρὸν γὰρ οὐδὲ ἓν οὔτε γέγονεν οὔτε ἐστὶν οὔτε ἔσται ἐν ⟨τῷ⟩ κόσμῳ.", "st": "XII.15e"}, {"sp": "N", "t": "ζῷον γὰρ ἠθέλησεν ὁ πατὴρ αὐτὸ⟨ν⟩ εἶναι ἔστ’ ἂν συνεστήκῃ·", "st": "XII.15f"}, {"sp": "N", "t": "διὸ καὶ θεὸν εἶναι ἀνάγκη. πῶς ἂν οὖν δύναιτο, ὦ τέκνον, ἐν τῷ θεῷ, ἐν τῇ τοῦ πατρὸς εἰκόνι, ἐν τῷ τῆς ζωῆς πληρώματι, νεκρὰ εἶναι;", "st": "XII.16"}, {"sp": "N", "t": "ἡ γὰρ νεκρότης φθορά ἐστιν, ἡ δὲ φθορὰ ἀπώλεια.", "st": "XII.16b"}, {"sp": "N", "t": "πῶς οὖν μέρος τι δύναται φθαρῆναι τοῦ ἀφθάρτου, ἢ ἀπολέσ⟨θ⟩αι τι τοῦ θεοῦ;", "st": "XII.16c"}, {"sp": "N", "t": "— Οὐκ ἀποθνήσκει οὖν, ὦ πάτερ, τὰ ἐν αὐτῷ ζῷα, ὄντα αὐτοῦ μέρη;", "st": "XII.16d"}, {"sp": "N", "t": "— Εὐφήμησον, ὦ τέκνον, πλανώμενος τῇ προσηγορίᾳ τοῦ γινομένου.", "st": "XII.16e"}, {"sp": "N", "t": "οὐ γὰρ ἀποθνήσκει, ὦ τέκνον, ἀλλ’ ὡς σύνθετα σώματα διαλύεται.", "st": "XII.16f"}, {"sp": "N", "t": "ἡ δὲ διάλυσις οὐ θάνατός ἐστιν, ἀλλὰ κράματος †διάλυσις†· διαλύεται δὲ οὐχ ἵν’ ἀπόληται, ἀλλ’ ἵνα νέα γένηται.", "st": "XII.16g"}, {"sp": "N", "t": "ἐπεὶ τίς τῆς ζωῆς ἐστιν ἡ ἐνέργεια; οὐχὶ κίνησις; τί οὖν ἐν τῷ κόσμῳ ἀκίνητον; οὐδέν, ὦ τέκνον.", "st": "XII.16h"}, {"sp": "N", "t": "— Οὐδ’ ἡ γῆ ἀκίνητός σοι δοκεῖ, ὦ πάτερ;", "st": "XII.17"}, {"sp": "N", "t": "— Οὔ, τέκνον, ἀλλὰ καὶ πολυκίνητος μόνη ἥδε καὶ στάσιμος.", "st": "XII.17b"}, {"sp": "N", "t": "πῶς οὐκ ἂν γελοῖον εἴη τὴν τροφὸν πάντων ἀκίνητον εἶναι, τὴν φύουσαν καὶ γεννῶσαν τὰ πάντα;", "st": "XII.17c"}, {"sp": "N", "t": "ἀδύνατον γὰρ χωρὶς κινήσεως φύειν τι [τὸν φύοντα].", "st": "XII.17d"}, {"sp": "N", "t": "γελοιότατον δὲ ἐπύθου, εἰ τὸ τέταρτον μέρος ἀργὸν ἐστ[α]ι· οὐδὲν γὰρ ἕτερον σημαίνει τὸ ἀκίνητον σῶμα ἢ ἀργίαν.", "st": "XII.17e"}, {"sp": "N", "t": "πᾶν τοίνυν ἴσθι καθολικῶς, ὦ τέκνον, τὸ ὂν ἐν κόσμῳ κινούμενον [ἢ κατὰ μείωσιν ἢ αὔξησιν]·", "st": "XII.18"}, {"sp": "N", "t": "τὸ δὲ κινούμενον καὶ ζῇ. τὸ δὲ ζῶ[ο]ν πᾶν οὐκ ἀνάγκη τὸ αὐτὸ ⟨ἀεὶ⟩ εἶναι·", "st": "XII.18b"}, {"sp": "N", "t": "ὢν γὰρ ὁμοῦ σύμπας ὁ κόσμος ἀμετάβλητος, ὦ τέκνον, ἐστί, τὰ δὲ μέρη αὐτοῦ πάντα μεταβλητά, οὐδὲν δὲ φθαρτὸν ἢ ἀπολλύμενον·", "st": "XII.18c"}, {"sp": "N", "t": "αἱ δὲ προσηγορίαι τοὺς ἀνθρώπους ταράττουσιν. οὐ γὰρ ἡ γένεσίς ἐστι ζωῆ⟨ς ἀρχή⟩, ἀλλ’ [ἡ] αἰσθήσεως· οὐδὲ ἡ μεταβολὴ θάνατος, ἀλλὰ λήθη.", "st": "XII.18d"}, {"sp": "N", "t": "τούτων τοίνυν οὕτως ἐχόντων, ἀθάνατα πάντα ἐξ ὧν πᾶν ζῷον συνέστηκε⟨ν⟩, ἡ ὕλη [ζωή,] τὸ πνεῦμα [ὁ νοῦς], ⟨ἡ⟩ ψυχὴ ἐξ οὗ πᾶν ζῷον συνέστηκε·", "st": "XII.18e"}, {"sp": "N", "t": "πᾶν ἄρα ζῷον ἀθάνατον δι⟨ὰ τὴν ἀθανασίαν⟩ αὐτῶν. πάντων δὲ μᾶλλον ⟨ἀθάνατος⟩ ὁ ἄνθρωπος, ὁ καὶ τοῦ θεοῦ δεκτικὸς καὶ τῷ θεῷ συνουσιαστικός.", "st": "XII.19"}, {"sp": "N", "t": "τούτῳ γὰρ μόνῳ τῷ ζῴῳ ὁ θεὸς ὁμιλεῖ, νυκτὸς μὲν δι’ ὀνείρων, ἡμέρας δὲ διὰ συμβόλων, καὶ διὰ πάντων αὐτῷ προλέγει τὰ μέλλοντα, διὰ ὀρνέων, διὰ σπλάγχνων, διὰ πνεύματος, διὰ δρυός·", "st": "XII.19b"}, {"sp": "N", "t": "διὸ καὶ ἐπαγγέλλεται ὁ ἄνθρωπος ἐπίστασθαι τὰ προγεγενημένα καὶ ἐνεστῶτα καὶ μέλλοντα.", "st": "XII.19c"}, {"sp": "N", "t": "κἀκεῖνο δὲ ὅρα, ὦ τέκνον, ὅτι ἕκαστον τῶν ζῴων ἑνὶ μέρει ἐπιφοιτᾷ τοῦ κόσμου, τὰ μὲν ἔνυδρα τῷ ὕδατι, τὰ δὲ χερσαῖα τῇ γῇ, τὰ δὲ μετάρσια τῷ ἀέρι· ὁ δὲ ἄνθρωπος τούτοις πᾶσι χρῆται, γῇ, ὕδατι, ἀέρι [πυρί]· ὁρᾷ δὲ καὶ οὐρανόν, ἅπτεται δὲ καὶ τούτου αἰσθήσει.", "st": "XII.20"}, {"sp": "N", "t": "⟨…⟩ [ὁ δὲ θεὸς καὶ περὶ πάντα καὶ διὰ πάντων.] †ἐνέργεια γάρ ἐστι δύναμις.† καὶ οὐδὲν δύσκολόν ἐστι νοῆσαι τὸν θεόν, ὦ τέκνον, εἰ δὲ θέλεις, αὐτὸν καὶ θεωρῆσαι.", "st": "XII.20b"}, {"sp": "N", "t": "ἴδε τὴν τάξιν τοῦ κόσμου [καὶ τὴν εὐκοσμίαν τῆς τάξεως]· ἴδε τὴν ἀνάγκην τῶν φαινομένων, καὶ τὴν πρόνοιαν τῶν γεγονότων τε καὶ γινομένων· ἴδε τὴν ὕλην πληρεστάτην οὖσαν ζωῆς· ⟨ἴδε⟩ τὸν τηλικοῦτον θεὸν κινούμενον μετὰ πάντων ⟨τῶν ἐνόντων⟩ [ἀγαθῶν καὶ καλῶν] [θεῶν τε καὶ δαιμόνων καὶ ἀνθρώπων].", "st": "XII.21"}, {"sp": "N", "t": "— Ἀλλ’ αὗται, ὦ πάτερ, ἐνέργειαι ὅλως εἰσίν.", "st": "XII.21b"}, {"sp": "N", "t": "— Εἰ οὖν ἐνέργειαί [ὅλως] εἰσιν, ὦ τέκνον, ὑπὸ τίνος [οὖν] ἐνεργοῦνται [ὑπὸ] ἄλλου ⟨ἢ τοῦ⟩ θεοῦ;", "st": "XII.21c"}, {"sp": "N", "t": "ἢ ἀγνοεῖς ὅτι ὥσπερ τοῦ κόσμου μέρη εἰσὶν οὐρανὸς καὶ γῆ καὶ ὕδωρ καὶ ἀήρ, τὸν αὐτὸν τρόπον μέρη ἐστὶ ⟨τοῦ⟩ θεοῦ [ζωὴ καὶ ἀθανασία καὶ] εἱμα⟨ρμένη⟩ καὶ ἀνάγκη καὶ πρόνοια καὶ φύσις [καὶ ψυχὴ καὶ νοῦς];", "st": "XII.21d"}, {"sp": "N", "t": "[καὶ τούτων πάντων ἡ διαμονὴ] [τὸ λεγόμενον ἀγαθόν.] καὶ οὐκ [ἔτι] ἔστι τι τῶν γινομένων ἢ τῶν γεγονότων ὅπου οὐκ ἔστιν ὁ θεός.", "st": "XII.21e"}, {"sp": "N", "t": "— Ἐν τῇ ὕλῃ οὖν, ὦ πάτερ;", "st": "XII.22"}, {"sp": "N", "t": "— Ἡ γὰρ ὕλη, ὦ τέκνον, χωρὶς θεοῦ ⟨τί⟩ ἐστιν, ἵνα τόπον αὐτῇ ἀπομερίσῃς [τόπον];", "st": "XII.22b"}, {"sp": "N", "t": "τί δὲ [ους] ἂν ἢ σωρὸν αὐτὴν οἴει εἶναι, μὴ ἐνεργουμένην; εἰ δὲ ἐνεργεῖται, ὑπὸ τίνος ἐνεργεῖται; τὰς γὰρ ἐνεργείας ἔφαμεν εἶναι μέρη τοῦ θεοῦ.", "st": "XII.22c"}, {"sp": "N", "t": "ὑπὸ τίνος οὖν ζωοποιεῖται τὰ πάντα ζῷα; ὑπὸ τίνος ἀθανατίζεται τὰ ἀθάνατα; ὑπὸ τίνος μεταβάλλεται τὰ μεταβλητά;", "st": "XII.22d"}, {"sp": "N", "t": "εἴτε δὲ ὕλην, εἴτε σῶμα, εἴτε οὐσίαν φῄς, ἴσθι καὶ ταύτας οὔσας ἐνεργείας τοῦ θεοῦ· ⟨ὁ γὰρ θεὸς⟩ καὶ ⟨τῆς⟩ ὕλη⟨ς⟩ ἐνεργεῖ τὴν ὑλότητα, καὶ τῶν σωμάτων ⟨τὴν⟩ σωματότητα, καὶ ⟨τ⟩ῆ⟨ς⟩ οὐσία⟨ς⟩ τὴν οὐσιότητα. καὶ τοῦτο ἔστιν ὁ θεός, τὸ πᾶν·", "st": "XII.22e"}, {"sp": "N", "t": "ἐν δὲ τῷ παντὶ οὐδέν ἐστιν ὃ μὴ ἔστιν. ὅθεν οὔτε μέγεθος οὔτε τόπος οὔτε ποιότης οὔτε σχῆμα οὔτε χρόνος παρὰ τὸν θεόν ἐστι· πᾶν γάρ ἐστι, τὸ δὲ πᾶν διὰ πάντων καὶ περὶ πάντα.", "st": "XII.23"}, {"sp": "N", "t": "τοῦτον [τὸν λόγον], ὦ τέκνον, προσκύνει καὶ θρήσκευε. θρησκεία δὲ τοῦ θεοῦ μία ἐστί, μὴ εἶναι κακόν.", "st": "XII.23b"}, {"sp": "HDR", "t": "Ἐν ὄρει λόγος ἀπόκρυφος περὶ παλιγγενεσίας"}, {"sp": "N", "t": "Ἐν τοῖς γενικοῖς, ὦ πάτερ, αἰνιγματωδῶς καὶ οὐ τηλαυγῶς ἔφρασας, περὶ θειότητος διαλεγόμενος·", "st": "XIII.1"}, {"sp": "N", "t": "οὐκ ἀπεκάλυψας φάμενος ⟨γὰρ⟩ μηδένα δύνασθαι σωθῆναι πρὸ τῆς παλιγγενεσίας, ἐμοῦ τε σοῦ ἱκέτου γενομένου †ἐπὶ τῆς τοῦ ὄρους μεταβάσεως† μετὰ τὸ σὲ ἐμοὶ διαλεχθῆναι [πυθομένου] τὸν τῆς παλιγγενεσίας λόγον μαθεῖν, ὅτι τοῦτον παρὰ πάντα μόνον ἀγνοῶ, ⟨οὔπω ἠξίωσας⟩ καὶ ἔφης ὅταν μέλλῃς ⟨τοῦ⟩ κόσμου ἀπαλλοτριοῦσθαι παραδιδόναι μοι ⟨παραδώσω.", "st": "XIII.1b"}, {"sp": "N", "t": "ἐγὼ δὲ ἤδη⟩ ἕτοιμος ἐγενόμην, καὶ ἀπηλλοτρίωσα τὸ ἐν ἐμοὶ φρόνημα ἀπὸ τῆς τοῦ κόσμου ἀπάτης·", "st": "XIII.1c"}, {"sp": "N", "t": "σὺ δέ μου καὶ τὰ ὑστερήματα ἀναπλήρωσον, ὡς ἔφης μοι, παλιγγενεσίαν παραδοῦναι προθέμενος [ἐκ φωνῆς ἢ κρυβήν].", "st": "XIII.1d"}, {"sp": "N", "t": "ἀγνοῶ, ὦ τρισμέγιστε, ἐξ οἵας μήτρας ἄνθρωπος ⟨ἀν⟩αγεννηθ⟨εί⟩η ⟨ἄν⟩, σπορᾶς δὲ ποίας.", "st": "XIII.1e"}, {"sp": "N", "t": "— Ὦ τέκνον, σοφία ⟨ἡ⟩ μήτρα, ἐν σιγῇ ⟨κύουσα⟩, καὶ ἡ σπορὰ τὸ ἀληθινὸν ἀγαθόν.", "st": "XIII.2"}, {"sp": "N", "t": "— Τίνος σπείραντος, ὦ πάτερ; τὸ γὰρ σύνολον ἀπορῶ.", "st": "XIII.2b"}, {"sp": "N", "t": "— Τοῦ θελήματος τοῦ θεοῦ, ὦ τέκνον.<br>— ⟨ὑπουργῶν⟩.", "st": "XIII.2c"}, {"sp": "N", "t": "— Καὶ ποταπὸς ὁ γεννώμενος, ὦ πάτερ; ἄμοιρος γὰρ τῆς ἐν ἐμοὶ οὐσίας καὶ τῆς νοητῆς", "st": "XIII.2d"}, {"sp": "N", "t": "— Ἄλλος [ἔσται] ὁ γεννώμενος, θεοῦ θεὸς παῖς, τὸ πᾶν, ἐν παντί· ⟨μοῖραν ἔχει⟩, ἐκ πασῶν δυνάμεων συνεστώς.", "st": "XIII.2e"}, {"sp": "N", "t": "— Αἴνιγμά μοι λέγεις, ὦ πάτερ, καὶ οὐχ ὡς πατὴρ υἱῷ διαλέγῃ.", "st": "XIII.2f"}, {"sp": "N", "t": "— Τοῦτο τὸ γένος, ὦ τέκνον, οὐ διδάσκεται, ἀλλ’ ὅταν θέλῃ ὑπὸ τοῦ θεοῦ, ἀναμιμνήσκεται.", "st": "XIII.2g"}, {"sp": "N", "t": "— Ἀδύνατά μοι λέγεις, ὦ πάτερ, καὶ βεβιασμένα. ὅθεν πρὸς ταῦτα ὀρθῶς ἀντειπεῖν ἔχω ⟨ἆρ’⟩ ἀλλότριος [υἱὸς] πέφυκα τοῦ πατρικοῦ γένους;", "st": "XIII.3"}, {"sp": "N", "t": "μὴ φθόνει μοι, πάτερ· γνήσιος υἱός εἰμι· διάφρασόν μοι τῆς παλιγγενεσίας τὸν τρόπον.", "st": "XIII.3b"}, {"sp": "N", "t": "— Τί εἴπω, ὦ τέκνον; οὐκ ἔχω λέγειν πλὴν τοῦτο· ὁρῶ[ν] τι⟨ν’⟩ ἐν ἐμοὶ ἄπλαστον ἰδέαν γεγενημένην ἐξ ἐλέου θεοῦ, καὶ ἐμαυτὸν ⟨δι⟩εξελήλυθα εἰς ἀθάνατον σῶμα·", "st": "XIII.3c"}, {"sp": "N", "t": "καί εἰμι νῦν οὐχ ὁ πρίν, ἀλλ’ ⟨ἀν⟩εγεννήθην ἐν νῷ, τὸ πρᾶγμα τοῦτο οὐ διδάσκεται οὐδὲ τῷ πλαστῷ τούτῳ στοιχείῳ δι’ οὗ ἐστιν ἰδεῖν καὶ διαλέλυταί μοι τὸ πρῶτον [σύνθετον] εἶδος.", "st": "XIII.3d"}, {"sp": "N", "t": "οὐκέτι κεχρω⟨μάτ⟩ισμαι καὶ ἁφὴν ἔχω καὶ μέτρον, ἀλλότριος δὲ τούτων εἰμὶ νῦν, [ὁρᾷς με ὦ τέκνον ὀφθαλμοῖς] ⟨καὶ πάντων⟩ ὅσα [δὲ] κατανοεῖς ἀτενίζων σωματικῇ ὁράσει.", "st": "XIII.3e"}, {"sp": "N", "t": "οὐκ ὀφθαλμοῖς τ⟨οι⟩ούτοις θεωροῦμαι νῦν, ὦ τέκνον.", "st": "XIII.3f"}, {"sp": "N", "t": "— Εἰς μανίαν με οὐκ ὀλίγην καὶ οἴστρησιν φρενῶν ἐνέσεισας, ὦ πάτερ. ἐμαυτὸν γὰρ νῦν οὐχ ὁρῶ;", "st": "XIII.4"}, {"sp": "N", "t": "— Εἴθε, ὦ τέκνον, καὶ σὺ σεαυτὸν διεξεληλύθεις, ⟨ἵνα εἶδες, μὴ⟩ ὡς οἱ ἐν ὕπνῳ ὀνειροπολούμενοι, ⟨ἀλλὰ⟩ χωρὶς ὕπνου.", "st": "XIII.4b"}, {"sp": "N", "t": "— Λέγε μοι καὶ τοῦτο· τίς ἐστι γενεσιουργὸς τῆς παλιγγενεσίας;", "st": "XIII.4c"}, {"sp": "N", "t": "— Ὁ τοῦ θεοῦ παῖς ἄνθρωπος εἷς θελήματι θεοῦ.", "st": "XIII.4d"}, {"sp": "N", "t": "— Νῦν τὸ λοιπόν, ὦ πάτερ, εἰς ἀφασίαν με ἤνεγκας. τῶν πρὶν ἀπολειφθεὶς φρενῶν. τὸ γὰρ μέγεθος βλέπω τὸ σὸν τὸ αὐτό, ὦ πάτερ, σὺν τῷ χαρακτῆρι.", "st": "XIII.5"}, {"sp": "N", "t": "— Καὶ ἐν τούτῳ ψεύδῃ· τὸ γὰρ θνητὸν εἶδος καθ’ ἡμέραν ἀλλάσσεται· χρόνῳ γὰρ τρέπεται εἰς αὔξησιν καὶ μείωσιν, ὡς ψεῦδος ⟨ὄν⟩.", "st": "XIII.5b"}, {"sp": "N", "t": "— Τί οὖν ἀληθές ἐστιν, ὦ τρισμέγιστε;", "st": "XIII.6"}, {"sp": "N", "t": "— Τὸ μὴ θολούμενον, ὦ τέκνον, τὸ μὴ ⟨πε⟩ριοριζόμενον, τὸ ἀχρώματον, τὸ ἀσχημάτιστον, τὸ ἄτρεπτον, τὸ γυμνόν, τὸ φα[ι]νόν, τὸ αὑτῷ καταληπτόν, τὸ ἀναλλοίωτον, τὸ ἀγαθὸν τὸ ἀσώματον.", "st": "XIII.6b"}, {"sp": "N", "t": "— Μέμηνα ὄντως, ὦ πάτερ, δοκοῦντος γάρ μου ὑπὸ σοῦ σοφοῦ γεγονέναι, ἐνεφράχθησαν αἱ αἰσθήσεις ⟨προβληθέντος⟩ τούτου μοι τοῦ νοήματος.", "st": "XIII.6c"}, {"sp": "N", "t": "— Οὕτως ἔχει, ὦ τέκνον. τὸ μὲν ἀνωφερὲς [ὡς πῦρ] καὶ κατωφερὲς [ὡς γῆ] καὶ ὑγρὸν [ὡς ὕδωρ] καὶ σύμπνοον [ὡς ἀὴρ] ⟨αἰσθήσει ὑποπίπτει· τὸ δὲ τούτοις ἀνόμοιον⟩ πῶς αἰσθητῶς οὕτω νοήσεις, τὸ μὴ σκληρόν, τὸ μὴ ὑγρόν, τὸ †ἀσφίγγωτον†, τὸ μὴ διαλυόμενον, τὸ μόνον δυνάμει [καὶ ἐνεργείᾳ] νοούμενον, δεόμενον δὲ τοῦ δυναμένου νοεῖν [τὴν ἐν θεῷ γένεσιν];", "st": "XIII.6d"}, {"sp": "N", "t": "— ἀδύνατος οὖν εἰμι, ὦ πάτερ;", "st": "XIII.7"}, {"sp": "N", "t": "— Μὴ γένοιτο, ὦ τέκνον. ἐπίσπασαι εἰς ἑαυτόν, καὶ ἐλεύσεται· θέλησον, καὶ γίνεται. κατάργησον τοῦ σώματος τὰς αἰσθήσεις, καὶ ἔσται ἡ γένεσις τῆς θεότητος. ⟨... δεῖ⟩ καθᾶραι σεαυτὸν ἀπὸ τῶν ἀλόγων τῆς ὕλης τιμωριῶν.", "st": "XIII.7b"}, {"sp": "N", "t": "— Τιμωροὺς γὰρ ἐν ἐμαυτῷ ἔχω, ὦ πάτερ;", "st": "XIII.7c"}, {"sp": "N", "t": "— Οὐκ ὀλίγους, ὦ τέκνον, ἀλλὰ καὶ φοβεροὺς καὶ πολλούς.", "st": "XIII.7d"}, {"sp": "N", "t": "— Ἀγνοῶ, ὦ πάτερ.", "st": "XIII.7e"}, {"sp": "N", "t": "— Μία αὕτη, ὦ τέκνον, τιμωρία, ἡ ἄγνοια. δευτέρα λύπη· τρίτη ἀκρασία· τετάρτη ἐπιθυμία· πέμπτη ἀδικία· ἕκτη πλεονεξία· ἑβδόμη ἀπάτη· ὀγδόη φθόνος· ἐνάτη δόλος· δεκάτη ὀργή· ἑνδεκάτη προπέτεια·", "st": "XIII.7f"}, {"sp": "N", "t": "δωδεκάτη κακία. εἰσὶ δὲ καὶ αὗται τὸν ἀριθμὸν δώδεκα, ὑπὸ δὲ ταύταις πλείονες ἄλλαι, ὦ τέκνον, ⟨αἳ⟩ διὰ τῆς τοῦ δεσμωτηρίου τοῦ σώματος αἰσθήσεως πάσχειν ἀναγκάζουσι τὸν ἐν τῷ δεσμωτηρίῳ τοῦ σώματος δεδε⟨μ⟩ένον ἄνθρωπον. ἀφίστανται δὲ αὗται [οὐκ] ἀθρόως ἀπὸ τοῦ ἐλεηθέντος ὑπὸ τοῦ θεοῦ, καὶ οὕτω συνίσταται ὁ.", "st": "XIII.7g"}, {"sp": "N", "t": "⟨οὗτος ὁ⟩ τῆς παλιγγενεσίας τρόπος [καὶ] λόγος.", "st": "XIII.7h"}, {"sp": "N", "t": "λοιπὸν σιώπησον, ὦ τέκνον, καὶ εὐφήμησον· †καὶ διὰ τοῦτο οὐ καταπαύσει† τὸ ἔλεος εἰς ἡμᾶς ἀπὸ τοῦ θεοῦ.", "st": "XIII.8"}, {"sp": "N", "t": "χαῖρε λοιπόν, ὦ τέκνον, ἀνακαθαιρόμενος ταῖς τοῦ θεοῦ δυνάμεσιν· ⟨πάρεισι γὰρ⟩ εἰς συνάρθρωσιν τοῦ λόγου.", "st": "XIII.8b"}, {"sp": "N", "t": "ἦλθεν ἡμῖν γνῶσις θεοῦ· ταύτης ἐλθούσης, ὦ τέκνον, ἐξηλάθη ἡ ἄγνοια.", "st": "XIII.8c"}, {"sp": "N", "t": "ἦλθεν ἡμῖν [γνῶσις] χαρά[ς]· παραγενομένης ταύτης, ὦ τέκνον, ἡ λύπη φεύξεται εἰς τοὺς χωροῦντας αὐτήν. ⟨τρίτην⟩ δύναμιν καλῶ ἐπὶ χαρᾷ τὴν ἐγκράτειαν. ὦ δύναμις ἡδίστη· προσλάβωμεν αὐτήν, ὦ τέκνον, ἀσμενέστατα. πῶς ἅμα τῷ παραγενέσθαι ἀπώσατο τὴν ἀκρασίαν.", "st": "XIII.8d"}, {"sp": "N", "t": "τετάρτην δὲ νῦν καλῶ καρτερίαν, τὴν κατὰ τῆς ἐπιθυμίας δύναμιν.⟨…⟩ ὁ βαθμὸς οὗτος, ὦ τέκνον, δικαιοσύνης ἐστὶν ἕδρασμα.", "st": "XIII.8e"}, {"sp": "N", "t": "χωρὶς γὰρ κτίσεως ἰδὲ πῶς τὴν ἀδικίαν ἐξήλασεν· χωρὶς γὰρ κρίσεως ἐδικαιώθημεν, ὦ τέκνον, ἀδικίας ἀπούσης.", "st": "XIII.8f"}, {"sp": "N", "t": "ἕκτην δύναμιν καλῶ εἰς ἡμᾶς τὴν κατὰ τῆς πλεονεξίας, ⟨τὴν⟩ κοινωνίαν.", "st": "XIII.8g"}, {"sp": "N", "t": "ἀποστάσης δὲ ⟨τῆς πλεονεξίας... ἑβδόμην⟩ ἐπικαλῶ τὴν ἀλήθειαν. φεῦγε[ι] ἀπάτη· ἀλήθεια παραγίνεται.", "st": "XIII.8h"}, {"sp": "N", "t": "ἰδὲ πῶς τὸ ἀγαθὸν πεπλήρωται, ὦ τέκνον, παραγενομένης τῆς ἀληθείας. φθόνος γὰρ ἀφ’ ἡμῶν ἀπέστη ⟨καὶ αἱ λοιπαὶ τιμωρίαι⟩. τῇ δὲ ἀληθείᾳ καὶ τὸ ἀγαθὸν ἐπεγένετο ἅμα ζωῇ καὶ φωτί.", "st": "XIII.8i"}, {"sp": "N", "t": "καὶ οὐκέτι ἐπῆλθεν οὐδεμία τοῦ σκότους τιμωρία, ἀλλ’ ἐξέπτησαν [νικηθεῖσαι] ῥοίζῳ.", "st": "XIII.8j"}, {"sp": "N", "t": "ἔγνωκας, ὦ τέκνον, τῆς παλιγγενεσίας τὸν τρόπον [τῆς δεκάδος παραγινομένης] ⟨οὕτω δή⟩, ὦ τέκνον, συνετέθη ⟨ἡ⟩ νοερὰ [γένεσις] ⟨οὐσία⟩, [καὶ τὴν δωδεκάτην ἐξελαύνει,] καὶ ἐθεώ[ρη]θημεν τῇ ⟨ταύτης⟩ γενέσει.", "st": "XIII.10"}, {"sp": "N", "t": "ὅστις οὖν ἔτυχε κατὰ τὸ ἔλεος τῆς κατὰ θεὸν γενέσεως, τὴν σωματικὴν αἴσθησιν καταλιπὼν ἑαυτὸν γνωρίζει ἐκ [τούτων] ⟨δυνάμεων⟩ συνιστάμενον, καὶ ⟨γνωρίσας⟩ εὐφραίνεται.", "st": "XIII.10b"}, {"sp": "N", "t": "— ⟨Οὐσί⟩α καινὴ[ς] γενόμενος ὑπὸ τοῦ θεοῦ, ὦ πάτερ, φαντάζομαι οὐχ ὁράσει ὀφθαλμῶν, ἀλλὰ τῇ [διὰ δυνάμεων] νοητικῇ ἐνεργείᾳ.", "st": "XIII.11"}, {"sp": "N", "t": "ἐν οὐρανῷ εἰμι, ἐν γῇ, ἐν ὕδατι, ἐν ἀέρι· ἐν ζῴοις εἰμί, ἐν φυτοῖς· ἐν γαστρί, πρὸ γαστρός, μετὰ γαστέρα· πανταχοῦ ⟨πάρειμι⟩.", "st": "XIII.11b"}, {"sp": "N", "t": "— [Ἀλλ’ ἔτι τοῦτό μοι εἰπέ, πῶς αἱ τιμωρίαι τοῦ σκότους, οὖσαι ἀριθμῷ δώδεκα, ὑπὸ δέκα δυνάμεων ἀπωθοῦνται. τίς ὁ τρόπος, ὦ τρισμέγιστε;", "st": "XIII.11c"}, {"sp": "N", "t": "— Τὸ σκῆνος τοῦτο, καὶ ὦ τέκνον, ὃ καὶ⟩ διεξεληλύθαμεν, ἐκ τοῦ ζῳοφόρου κύκλου συνέστη, καὶ τούτου συνεστῶτος ἐξ ἀριθμῶν δώδεκα ὄντων τὸν ἀριθμόν, ⟨γεννῶντος⟩ φύσεως μιᾶς παντομόρφου⟨ς⟩ ἰδέας εἰς πλάνην τοῦ ἀνθρώπου· καὶ τούτου συνεστῶτος ἐκ ζῳδίων δώδεκα ὄντων τὸν ἀριθμόν, διαζυγ⟨ί⟩αι ἐν αὐταῖς εἰσιν, ὦ τέκνον, ⟨δώδεκα.⟩ εἰσὶ δὲ καὶ ἀδιόριστοι, ἡνωμέναι ἐν τῇ πράξει· ἀχώριστος ⟨γάρ⟩ ἐστιν ἡ προπέτεια τῆς ὁρμῆς.", "st": "XIII.12"}, {"sp": "N", "t": "εἰσὶ δὲ καὶ ἀδιόριστοι εἰκότως οὖν κατὰ τὸν ὀρθὸν λόγον τὴν ἀπόστασιν ποιοῦνται, καθὼς ⟨εἶπον, ἀθρόως⟩. καὶ κατὰ [τὸν ὀρθὸν] λόγον ἀπὸ δέκα δυνάμεων ἐλαύνονται, τουτέστιν ἀπὸ τῆς δεκάδος·", "st": "XIII.12b"}, {"sp": "N", "t": "ἡ γὰρ δεκάς, ὦ τέκνον, ἐστὶ ψυχογόνος. ζωὴ δὲ καὶ φῶς ἡνωμέναι εἰσὶν ἑνὰς· ὁ ⟨δὲ⟩ τῆς ἑνάδος ἀριθμὸς πέφυκε τοῦ [πνεύματος] ⟨τῆς δεκάδος ἀρχή⟩. ἡ ἑνὰς οὖν κατὰ λόγον τὴν δεκάδα ⟨ἐμπερι⟩έχει [καὶ ἡ δεκὰς τὴν ἑνάδα].] — Αὕτη ἐστὶν ἡ παλιγγενεσία, ὦ τέκνον, τὸ μηκέτι φαντάζεσθαι [εἰς] τὸ σῶμα τὸ τριχῆ διαστατόν, ⟨ἀλλὰ τὸ ἀσώματον.⟩", "st": "XIII.13"}, {"sp": "N", "t": "— Πάτερ, τὸ πᾶν ὁρῶ [καὶ] ἐμαυτὸν ⟨ὄντα⟩, ἐν τῷ νοῒ ⟨ὁρῶν⟩. Πάτερ, τὸ πᾶν ὁρῶ καὶ ἐμαυτὸν ἐν τῷ νοΐ.", "st": "XIII.13b"}, {"sp": "N", "t": "Αὕτη ἐστὶν ἡ παλιγγενεσία, ὦ τέκνον, τὸ μηκέτι φαντάζεσθαι εἰς τὸ σῶμα τὸ τριχῆ διαστατόν. διὰ τὸν λόγον τοῦτον τὸν περὶ τῆς παλιγγενεσίας εἰς ὃν ὑπεμνηματισάμην, ἵνα μὴ ὦμεν διάβολοι τοῦ παντὸς εἰς τοὺς πολλούς, εἰς οὓς ὁ θεὸς αὐτὸς θέλει. ⟨ἰ⟩δίᾳ τὸν λόγον τοῦτον τὸν περὶ τῆς παλιγγενεσίας [εἰς ὃν] εἰς οὓς ὁ θεὸς αὐτὸς θέλει ὑπεμνηματισάμην, ⟨οὐκ⟩ εἰς τοὺς πολλούς, ἵνα μὴ ⟨λογισθ⟩ῶμεν διάβολοι τοῦ παντός. εἰς τοὺς πολλοὺς εἰς οὓς ὁ θεὸς αὐτὸς θέλει.", "st": "XIII.13c"}, {"sp": "N", "t": "Εἰπέ μοι, ὦ πάτερ, τὸ σῶμα τοῦτο τὸ ἐκ δυνάμεων συνεστὸς λύσιν ἕξει ποτέ;", "st": "XIII.14"}, {"sp": "N", "t": "— Εὐφήμησον, καὶ μὴ ἀδύνατα φθέγγου, ἐπεὶ [ἁμαρτήσεις καὶ] ἀσεβή⟨σεις. μὴ ἐσβέσ⟩θη [σεται] σου ὁ ὀφθαλμὸς τοῦ νοῦ;", "st": "XIII.14b"}, {"sp": "N", "t": "τὸ αἰσθητὸν τῆς φύσεως σῶμα πόρρωθέν ἐστι [τῆς] ⟨τοῦ⟩ οὐσιώδους [γενέσεως]·", "st": "XIII.14c"}, {"sp": "N", "t": "τὸ μὲν γάρ ἐστι διαλυτόν, τὸ δὲ ἀδιάλυτον, καὶ τὸ μὲν θνητόν, τὸ δὲ ἀθάνατον.", "st": "XIII.14d"}, {"sp": "N", "t": "ἀγνοεῖς ὅτι θεὸς πέφυκας καὶ τοῦ ἑνὸς παῖς, ὃ κἀγώ;", "st": "XIII.14e"}, {"sp": "N", "t": "— Ἐβουλόμην, ὦ πάτερ, τὴν διὰ τοῦ ὕμνου εὐλογίαν ⟨μαθεῖν⟩, ἥν, καθὼς ἔφης, ἐπὶ τὴν ὀγδοάδα γενομένου σου ἀκούσ⟨εσθ⟩αί ⟨σε⟩ τῶν δυνάμεων καθὼς [ὀγδοάδα] ὁ Ποιμάνδρης ἐθέσπισε.", "st": "XIII.15"}, {"sp": "N", "t": "— ⟨Ὦ⟩ τέκνον, καλῶς σπεύδεις· κεκάθαρσαι γάρ, λυσάμ⟨ενος⟩ τὸ σκῆνος κεκαθαρμένος γάρ.", "st": "XIII.15b"}, {"sp": "N", "t": "ὁ Ποιμάνδρης, ὁ τῆς αὐθεντίας νοῦς, πλέον μοι τῶν ἐγγεγραμμένων οὐ παρέδωκεν, εἰδὼς ὅτι ἀπ’ ἐμαυτοῦ δυνήσομαι πάντα νοεῖν, καὶ ἀκούειν ὧν βούλομαι, καὶ ὁρᾶν τὰ πάντα·", "st": "XIII.15c"}, {"sp": "N", "t": "καὶ ἐπέτρεψέ μοι ἐκεῖνος †ποιεῖν τὰ καλά.† διὸ [κ] αἱ ἐν πᾶσι[ν αἱ] δυνάμεις καὶ ἐν ἐμοὶ ᾄδουσι.", "st": "XIII.15d"}, {"sp": "N", "t": "— Θέλω, πάτερ, ἀκοῦσαι, καὶ βούλομαι ταῦτα νοῆσαι.", "st": "XIII.15e"}, {"sp": "N", "t": "— Ἡσύχασον, ὦ τέκνον, καὶ τῆς ἁρμοζούσης τῇ παλιγγενεσίᾳ νῦν ἄκουε εὐλογίας τὸν ὕμνον τῆς παλιγγενεσίας, ὃν οὐκ ἔκρινα οὕτως εὐκόλως ἐκφάναι σοι εἰ μὴ σοι ἐπὶ τέλει τοῦ παντός.", "st": "XIII.16"}, {"sp": "N", "t": "[ὅθεν τοῦτο οὐ διδάσκεται, εἰ μὴ ἐπὶ τέλει τοῦ παντός, ἀλλὰ κρύπτεται ἐν σιγῇ.] [οὕτως οὖν, [ὦ τέκνον,] στὰς ἐν ὑπαίθρῳ τόπῳ, νότῳ ἀνέμῳ ἀποβλέπων, περὶ καταφορὰν ἡλίου [δύνοντος] προσκύνει·", "st": "XIII.16b"}, {"sp": "N", "t": "ὁμοίως ⟨δὲ⟩ καὶ ἀνιόντος πρὸς ἀπηλιώτην.] [ἡσύχασον, ὦ τέκνον.]", "st": "XIII.16c"}, {"sp": "N", "t": "[ὑμνῳδία κρυπτή.] Ἀνοιγήτω μοι πᾶς μοχλὸς ⟨τοῦ⟩· πᾶσα φύσις κόσμου προσδεχέσθω τοῦ ὕμνου τὴν ἀκοήν.", "st": "XIII.17"}, {"sp": "N", "t": "ἀνοίγηθι γῆ, ἀνοιγήτω μοι πᾶς μοχλὸς [ὄμβρου], τὰ δένδρα μὴ σείεσθε·", "st": "XIII.17b"}, {"sp": "N", "t": "ὑμνεῖν μέλλω τὸν [τῆς κτίσεως κύριον] καὶ τὸ πᾶν καὶ τὸ ἓν ⟨ὄντα⟩.", "st": "XIII.17c"}, {"sp": "N", "t": "ἀνοίγητε οὐρανοί, ἄνεμοί τε στῆτε· ὁ κύκλος ὁ ἀθάνατος [τοῦ θεοῦ] προσδεξάσθω μου τὸν λόγον.", "st": "XIII.17d"}, {"sp": "N", "t": "μέλλω γὰρ ὑμνεῖν τὸν κτίσαντα τὰ πάντα, τὸν πήξαντα τὴν γῆν καὶ οὐρανὸν κρεμάσαντα, [καὶ] ⟨τὸν⟩ †ἐπιτάξαντα† ἐκ τοῦ ὠκεανοῦ τὸ γλυκὺ ὕδωρ εἰς τὴν οἰκουμένην [καὶ ἀοίκητον], ὑπάρχειν εἰς διατροφὴν [καὶ κτίσιν] πάντων †ἀνθρώπων†, [τὸν] ⟨καὶ⟩ ἐπιτάξαντα πῦρ φανῆναι εἰς πᾶσαν πρᾶξιν θεοῖς τε καὶ ἀνθρώποις.", "st": "XIII.17e"}, {"sp": "N", "t": "δῶμεν πάντες ὁμοῦ αὐτῷ τὴν εὐλογίαν, τῷ ἐπὶ τῶν οὐρανῶν μετεώρῳ, τῷ πάσης φύσεως κτίστῃ.", "st": "XIII.17f"}, {"sp": "N", "t": "οὗτός ἐστιν ὁ τοῦ νο⟨ός⟩ μου ὀφθαλμός· [καὶ] δέξαιτο τῶν δυνάμεών μου τὴν εὐλογίαν.", "st": "XIII.18"}, {"sp": "N", "t": "αἱ δυνάμεις αἱ ἐν ἐμοί, ὑμνεῖτε τὸ ἓν καὶ τὸ πᾶν· συνᾴσατε τῷ θελήματί μου, πᾶσαι αἱ ἐν ἐμοὶ δυνάμεις.", "st": "XIII.18b"}, {"sp": "N", "t": "γνῶσις ἁγία, φωτισθεὶς ἀπὸ σοῦ, διὰ σοῦ τὸ νοητὸν φῶς ὑμνῶ[ν].", "st": "XIII.18c"}, {"sp": "N", "t": "⟨…⟩ χαίρω ἐν χαρᾷ νοῦ· πᾶσαι δυνάμεις [ὑμνεῖτε] ⟨χαίρετε⟩ σὺν ἐμοί.", "st": "XIII.18d"}, {"sp": "N", "t": "καὶ σύ μοι, ἐγκράτεια, ὕμνει· ⟨καρτερία... ⟩· δικαιοσύνη μου, τὸ δίκαιον ὕμνει δι’ ἐμοῦ· κοινωνία ἡ ἐμή, τὸ πᾶν ὕμνει δι’ ἐμοῦ· ὕμνει ἀλήθεια τὴν ἀλήθειαν. τὸ ἀγαθόν, ἀγαθὸν ⟨τὸ ἐν ἐμοί,⟩ ὕμνει·", "st": "XIII.18e"}, {"sp": "N", "t": "ζωὴ καὶ φῶς, ἀφ’ ὑμῶν εἰς ὑμᾶς χωρεῖ ἡ εὐλογία.", "st": "XIII.18f"}, {"sp": "N", "t": "εὐχαριστῶ σοι, πάτερ, ἐνέργεια τῶν δυνάμεών ⟨μου⟩· εὐχαριστῶ σοι, θεέ, †δύναμις τῶν ἐνεργειῶν μου†.", "st": "XIII.18g"}, {"sp": "N", "t": "ὁ σὸς λόγος δι’ ἐμοῦ ὑμνεῖ σέ· δι’ ἐμοῦ [δέξαι †τὸ πᾶν λόγῳ† λογικὴν θυσίαν.]", "st": "XIII.18h"}, {"sp": "N", "t": "ταῦτα βοῶσαι αἱ δυνάμεις αἱ ἐν ἐμοὶ τὸ πᾶν ὑμνοῦσι τὸ σὸν θέλημα τελοῦσι·", "st": "XIII.19"}, {"sp": "N", "t": "τὸ πᾶν ὑμνοῦσ⟨α⟩ι ⟨... τῇ⟩ σῇ βουλῇ ⟨…⟩ ἀπὸ σοῦ ἐπὶ σὲ τὸ πᾶν. ὁ σὸς λόγος δι’ ἐμοῦ ὑμνεῖ σέ· λόγον γὰρ τὸν ἐμὸν ποιμαίνει⟨ς σὺ⟩ ὁ νοῦς. δι’ ἐμοῦ δέξαι ἀπὸ πάντων λογικὴν θυσίαν· τὸ πᾶν ⟨γὰρ⟩ ἀπὸ σοῦ, ⟨καὶ⟩ ἐπὶ σὲ τὸ πᾶν. ⟨τὸν νοῦν⟩ τὸ⟨ν⟩ ἐν ἡμῖν σῶζε ζωὴ φώτιζε φῶς·", "st": "XIII.19b"}, {"sp": "N", "t": "⟨τὴν ψυχὴν...⟩ σῶζε ζωή. [†πνεῦμα θεέ† λόγον γὰρ τὸν σὸν ποιμαίνει ὁ νοῦς [†πνευματοφόρε δημιουργέ, σὺ εἶ ὁ θεός.†]", "st": "XIII.19c"}, {"sp": "N", "t": "ὁ σὸς ἄνθρωπος ταῦτα βοᾷ [διὰ πυρός, δι’ ἀέρος, διὰ γῆς, διὰ ὕδατος,] [διὰ πνεύματος,] διὰ τῶν κτισμάτων σοῦ, ἀπὸ τοῦ αἰῶνος ⟨τὴν⟩ εὐλογίαν εὑρών.", "st": "XIII.20"}, {"sp": "N", "t": "[καὶ] ὃ ζητῶ εἶδον· βουλῇ τῇ σῇ ἀναπέπαυμαι εἶδον·", "st": "XIII.20b"}, {"sp": "N", "t": "θελήματι τῷ σῷ ⟨ἀνεγεννήθην⟩. — Τὴν εὐλογίαν ταύτην λέγων, ὦ πάτερ, τέθεικα⟨ς⟩ καὶ ἐν κόσμῳ τῷ ἐμῷ", "st": "XIII.21"}, {"sp": "N", "t": "— Ἐν τῷ νοητῷ λέγε, τέκνον.", "st": "XIII.21b"}, {"sp": "N", "t": "— Ἐν τῷ νοητῷ, ὦ πάτερ, δύναμιν ἐκ τοῦ σοῦ ὕμνου, καὶ ⟨διὰ⟩ τῆς σῆς εὐλογίας ἐπιπεφώτισταί μου ὁ νοῦς. πλὴν θέλω κἀγὼ πέμψαι ἐξ ἰδίας φρενὸς εὐλογίαν τῷ θεῷ.", "st": "XIII.21c"}, {"sp": "N", "t": "— Ὦ τέκνον, μὴ ἀσκόπως.", "st": "XIII.21d"}, {"sp": "N", "t": "— Ἐν τῷ νῷ, ὦ πάτερ, ἃ θεωρῶ λέγω.", "st": "XIII.21e"}, {"sp": "N", "t": "Σοὶ ⟨ἐγώ, ὦ⟩ γενάρχα τῆς γενεσιουργίας, Τὰτ θεῷ πέμπω λογικὰς θυσίας. θεέ, σὺ ⟨ὁ⟩ πατήρ· [σὺ ὁ] κύριε, σὺ ὁ νοῦς. δέξαι ⟨εὐ⟩λογί[κ]ας ἃς θέλεις ἀπ’ ἐμοῦ· σοῦ γὰρ βουλομένου πάντα ⟨μοι⟩ τελεῖται.", "st": "XIII.21f"}, {"sp": "N", "t": "Εὖ ὦ τέκνον· ⟨ἔ⟩πεμψας δεκτὴν θυσίαν τῷ πάντων πατρὶ θεῷ. ἀλλὰ καὶ πρόσθες, ὦ τέκνον, διὰ τοῦ λόγου.", "st": "XIII.21g"}, {"sp": "N", "t": "— Εὐχαριστῶ σοι, πάτερ [⟨ὅτι⟩ ταῦτά μοι αἰνεῖς εὐξαμένῳ.", "st": "XIII.21h"}, {"sp": "N", "t": "— Χαίρω, τέκνον, ⟨ὡς⟩ καρποφορήσοντος ⟨σου...⟩ ἐκ τῆς ἀληθείας [τὰ ἀγαθὰ] τὰ ἀθάνατα τῆς ἀρετῆς γεννήματα· ⟨ἐπεὶ⟩ νοερῶς ἔγνως σεαυτὸν καὶ τὸν πατέρα τὸν ἡμέτερον.", "st": "XIII.22"}, {"sp": "N", "t": "τοῦτο μαθὼν παρ’ ἐμοῦ, τῆς ἀρετῆς σιγὴν ἐπάγγειλαι, ⟨ὦ⟩ μηδενὶ τέκνον ἐκφα[ι]νεῖν τῆς παλιγγενεσίας τὴν παράδοσιν, ἵνα μὴ ὡς διάβολοι ⟨τοῦ παντὸς⟩ λογισθῶμεν.", "st": "XIII.22b"}, {"sp": "N", "t": "⟨…⟩ ἱκανῶς γὰρ ἕκαστος ἡμῶν ⟨ἑαυτοῦ⟩ ἐπεμελήθη, ἐγώ τε [ὁ] λέγων σύ τε [ὁ] ἀκούων.", "st": "XIII.22c"}, {"sp": "N", "t": "νοερῶς ἔγνως σεαυτὸν καὶ τὸν πατέρα τὸν ἡμέτερον.", "st": "XIII.22d"}], []);})();
